// Rete PR — Worker Cloudflare: serve l'app e le API su D1.
// Accesso: Cloudflare Access (PIN via email) davanti al Worker; qui si verifica il token
// e si decide chi è admin (ADMIN_EMAILS) e quale capo staff corrisponde a ogni email (tabella utenti).

const HTML = "<!DOCTYPE html>\n<html lang=\"it\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Rete PR</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n/* VOICE: gestionale denso e veloce, pensato per centinaia di nomi\n   IDEA: il pass del backstage: fascia arancio piena, etichette nette, numeri grossi\n   PICTURE: lo strumento stesso, tabelle fitte, albero dello staff, colonne delle serate\n   COLOUR and TYPE: arancio dominante, rosso per i biglietti, giallo per i tavoli; Plus Jakarta Sans\n   LAYOUT: barra arancio compatta con le sezioni a pillola, contenuto a griglia stretta, liste lunghe che scorrono nel loro riquadro */\n:root{color-scheme:light dark;\n--bg:light-dark(#ffffff,#140c08);--panel:light-dark(#fff5ee,#22150e);--line:light-dark(#f1e1d6,#3a271c);\n--ink:light-dark(#2a1309,#fff1e8);--mute:light-dark(#8a6552,#c3a593);\n--or:#ff6a13;--inc:light-dark(#7a2e0e,#f3b98f);--red:light-dark(#e3301c,#ff5a3d);--yel:#ffbf1f;--ok:light-dark(#1f7a4d,#5fd39a)}\n:root[data-theme=light]{color-scheme:light}:root[data-theme=dark]{color-scheme:dark}\n*{box-sizing:border-box;min-width:0}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 \"Plus Jakarta Sans\",system-ui,sans-serif;overflow-x:clip}\nheader{background:var(--or);color:#2a1309;padding:12px max(3vw,14px)}\n.hd{max-width:1400px;margin:0 auto;display:flex;flex-wrap:wrap;gap:10px 24px;align-items:center}\nheader h1{margin:0;font-size:24px;font-weight:800;line-height:1;letter-spacing:-.02em}\nheader p{margin:3px 0 0;font-size:13px;font-weight:500;color:#5a2408}header p a{color:inherit;font-weight:700}\nnav{display:flex;gap:4px;overflow-x:auto;background:rgb(0 0 0/.12);padding:4px;border-radius:12px;margin-left:auto}\nnav a{flex:none;color:#2a1309;text-decoration:none;padding:7px 14px;border-radius:9px;font-weight:700;font-size:14px}\nnav a.on{background:#fff;box-shadow:0 1px 3px rgb(0 0 0/.15)}\nmain{max-width:1400px;margin:0 auto;padding:18px max(3vw,14px) 48px}\nh2{font-size:26px;line-height:1.1;margin:0;letter-spacing:-.02em;font-weight:800}\nh3{font-size:14px;margin:0 0 8px;font-weight:700}\n.sub{color:var(--mute);margin:2px 0 0;font-size:13px}\n.top{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;margin:0 0 14px}\n.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}\n.sp{flex:1}\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin:0 0 12px}\n.kpi{background:var(--panel);border-radius:10px;padding:8px 12px;border-top:3px solid var(--or)}\n.kpi b{display:block;font-size:22px;line-height:1.15;font-weight:800;font-variant-numeric:tabular-nums}\n.kpi span{color:var(--mute);font-size:12.5px}\n.grid3{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:10px;margin:0 0 12px}\n.grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,440px),1fr));gap:10px;margin:0 0 12px}\n.card{background:var(--panel);border-radius:12px;padding:10px 12px}\n.bars{max-height:190px;overflow-y:auto;padding-right:4px}\n.bar{display:grid;grid-template-columns:minmax(0,8.5em) minmax(0,1fr) 2.4em;gap:6px;align-items:center;font-size:13px;margin:2px 0}\n.bl{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.bt{height:9px;background:var(--line);border-radius:5px;overflow:hidden}\n.bt i{display:block;height:100%;background:linear-gradient(90deg,var(--or),var(--red));border-radius:5px}\n.bar b{text-align:right;font-variant-numeric:tabular-nums}\nbutton,.btn{font:inherit;font-weight:700;min-height:38px;padding:0 14px;border-radius:9px;border:1px solid var(--line);background:var(--bg);color:var(--ink);cursor:pointer;font-size:14px}\nbutton.pri{background:var(--red);border-color:var(--red);color:#fff}\nbutton.ghost{background:none;border-color:transparent;color:var(--red);padding:0 6px}\nbutton.danger{color:var(--red);border-color:var(--red)}\nbutton:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,nav a:focus-visible,summary:focus-visible{outline:3px solid var(--yel);outline-offset:2px}\ninput,select,textarea{font:inherit;font-size:16px;min-height:38px;padding:6px 10px;border-radius:9px;border:1px solid var(--line);background:var(--bg);color:var(--ink);width:100%}\ntextarea{min-height:90px}\nlabel{display:block;font-size:12.5px;color:var(--mute);font-weight:600}\nlabel>input,label>select,label>textarea{margin-top:3px;color:var(--ink)}\n.filters{display:grid;grid-template-columns:minmax(0,2fr) repeat(3,minmax(0,1fr)) auto;gap:8px;margin:0 0 8px;align-items:end}\n.tbl{max-height:68vh;overflow:auto;border:1px solid var(--line);border-radius:12px}\n.tbl.s{max-height:380px}\ntable{width:100%;border-collapse:collapse;font-size:13.5px}\nth{text-align:left;font-size:12px;color:var(--mute);font-weight:700;padding:7px 10px;background:var(--panel);position:sticky;top:0;z-index:1;white-space:nowrap}\nth[data-so]{cursor:pointer;user-select:none}th[data-so]:hover{color:var(--ink)}th.on{color:var(--red)}\ntd{padding:5px 10px;border-top:1px solid var(--line);vertical-align:middle}\ntbody tr:hover td{background:var(--panel)}\ntd.n,th.n{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}\n.note{color:var(--mute);font-size:12px;font-weight:400}\ntd .note.i{display:inline;margin-left:8px}td .note{display:block;max-width:28ch;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tag{display:inline-block;font-size:11.5px;font-weight:700;padding:1px 8px;border-radius:99px;background:var(--line);white-space:nowrap}\n.tag.staff{background:var(--red);color:#fff}.tag.capo{background:var(--yel);color:#2a1309}\n.link{background:none;border:0;padding:0;min-height:0;color:inherit;font-weight:700;text-align:left;cursor:pointer;font-size:inherit}\n.link:hover{color:var(--red);text-decoration:underline}\n.empty{color:var(--mute);font-size:13px;margin:4px 0}\n.tree{display:grid;gap:8px}\n.node{background:var(--panel);border-radius:12px;padding:8px 12px;border-left:4px solid var(--red)}\n.node .node{margin-top:6px;background:var(--bg);border:1px solid var(--line);border-left:4px solid var(--red)}.node>summary{list-style:none;cursor:pointer}.node>summary::-webkit-details-marker{display:none}\n.node>summary::before{content:\"▸\";color:var(--mute);margin-right:2px;display:inline-block;transition:transform .15s}\n.node[open]>summary::before{transform:rotate(90deg)}\n.node .c{background:var(--bg);border:1px solid var(--line);border-left:4px solid var(--yel);border-radius:10px;padding:6px 10px;margin-top:6px}\n.nh{display:flex;flex-wrap:wrap;gap:4px 12px;align-items:center}\n.tot{font-variant-numeric:tabular-nums;color:var(--mute);font-size:12.5px;white-space:nowrap}\n.tot b{color:var(--ink)}\n.leaves{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}\n.leaf{display:inline-flex;gap:5px;align-items:center;background:var(--bg);border:1px solid var(--line);border-radius:99px;padding:2px 4px 2px 10px;font-size:12.5px}\n.leaf>span{background:var(--panel);border-radius:99px;padding:0 7px;font-variant-numeric:tabular-nums;color:var(--mute)}\n.tabs{display:flex;flex-wrap:wrap;gap:4px;align-items:center;margin:0 0 12px}\n.tabs small{color:var(--mute);margin:0 2px 0 8px;font-size:12px;font-weight:600}\n.tabs button{min-height:32px;border-radius:99px;font-size:13px;padding:0 12px}\n.tabs button.on{background:var(--or);color:#2a1309;border-color:var(--or)}\n.fig{position:relative;min-height:200px}.fig.sm{min-height:140px}.fig>svg{position:absolute;inset:0;width:100%;height:100%}\n.fig text{font:11px \"Plus Jakarta Sans\",sans-serif;fill:var(--mute)}.fig .v{fill:var(--ink);font-weight:700}\n.scroll{overflow-x:auto}\n#modal{position:fixed;inset:0;background:rgb(30 10 2/.55);display:none;align-items:flex-start;justify-content:center;padding:3vh 10px;overflow-y:auto;z-index:9}\n#modal.on{display:flex}\n.sheet{background:var(--bg);border-radius:16px;width:min(720px,100%);padding:16px clamp(14px,3vw,22px);box-shadow:0 20px 60px rgb(0 0 0/.35);border-top:5px solid var(--or)}\n.form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 10px;margin:10px 0}\n.form .w{grid-column:1/-1}\n.msg{min-height:20px;color:var(--red);font-size:13px;margin:4px 0}\n.msg.ok{color:var(--ok)}\n.rl{max-height:50vh;overflow-y:auto;border:1px solid var(--line);border-radius:10px;margin:6px 0}\n.rr{display:grid;grid-template-columns:minmax(0,1fr) 70px 70px;}.rr.inc{grid-template-columns:minmax(0,1fr) 70px 70px 90px}.rr{gap:6px;align-items:center;padding:3px 10px;border-bottom:1px solid var(--line);font-size:13.5px}\n.rr:last-child{border-bottom:0}.rr.has{background:var(--panel)}\n.rr input{text-align:right;min-height:32px;padding:3px 8px}\n.chips{display:flex;flex-wrap:wrap;gap:4px;margin:4px 0 8px}\ndetails>summary{cursor:pointer}\n#toast{position:fixed;left:50%;bottom:16px;transform:translateX(-50%);background:var(--ink);color:var(--bg);padding:8px 16px;border-radius:9px;font-size:13px;opacity:0;transition:opacity .25s;pointer-events:none;z-index:10}\n#toast.on{opacity:1}\n#banner{display:none;background:var(--red);color:#fff;padding:6px max(3vw,14px);font-size:13px}\n@media(prefers-reduced-motion:reduce){#toast,.node>summary::before{transition:none}}\n@media(max-width:800px){.filters{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.filters>:first-child{grid-column:1/-1}nav{margin-left:0}}\n@media(max-width:600px){.form{grid-template-columns:minmax(0,1fr)}.stack thead{display:none}.stack tr{display:grid;padding-block:6px;border-top:1px solid var(--line)}.stack td{display:flow-root;border:0;padding:2px 10px;padding-inline-start:calc(7em + 10px);text-align:start}.stack td::before{content:attr(data-l);float:inline-start;width:6.5em;margin-inline-start:-7em;color:var(--mute);font-size:12px}.stack td:empty{display:none}.bar{grid-template-columns:minmax(0,7em) minmax(0,1fr) 2.2em}}\n</style>\n<script>new MutationObserver(()=>{for(const c of document.querySelectorAll('.stack td:not([data-l])')){let i=0,p=c;while(p=p.previousElementSibling)i+=p.colSpan;c.dataset.l=c.closest('table').rows[0].cells[i]?.textContent||''}}).observe(document,{childList:true,subtree:true})</script>\n</head>\n<body>\n<header><div class=\"hd\">\n  <div><h1>Rete PR</h1><p id=\"who\">Anagrafica, struttura dello staff e risultati delle serate</p></div>\n  <nav id=\"nav\">\n    <a href=\"#archivio\" data-v=\"archivio\">Archivio</a>\n    <a href=\"#struttura\" data-v=\"struttura\">Struttura</a>\n    <a href=\"#serate\" data-v=\"serate\" data-adm=\"1\">Serate</a>\n    <a href=\"#report\" data-v=\"report\">Report</a>\n    <a href=\"#punti\" data-v=\"punti\">Punti</a>\n    <a href=\"#accessi\" data-v=\"accessi\" data-adm=\"1\">Accessi</a>\n  </nav>\n</div></header>\n<div id=\"banner\"></div>\n<main id=\"main\"><p class=\"empty\">Caricamento dell'archivio…</p></main>\n<div id=\"modal\"><div class=\"sheet\" id=\"sheet\"></div></div>\n<div id=\"toast\"></div>\n<script>\n{\nconst S={me:null,utenti:[],so:{k:'ruolo',d:1},db:null,pr:[],loc:[],ser:[],got:{},q:'',fR:'',fS:'',fZ:'',rep:'all',repPr:'',draft:null,rq:'',charts:{}};\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst RUOLI={staff:'Capo staff',capo:'Capo PR',pr:'PR'};\nconst ORD={staff:0,capo:1,pr:2};\nconst nome=p=>p?([p.nome,p.cognome].filter(Boolean).join(' ')||'Senza nome'):'PR eliminato';\nconst byId=id=>S.pr.find(p=>p.id===id);\nconst figli=id=>S.pr.filter(p=>p.parent===id);\nconst norm=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/\\s+/g,' ').trim();\nconst fmtD=d=>{if(!d)return '—';const [y,m,g]=d.split('-');return `${g}/${m}/${y.slice(2)}`};\nconst sortNome=(a,b)=>nome(a).localeCompare(nome(b),'it');\nconst toast=t=>{const e=$('#toast');e.textContent=t;e.classList.add('on');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('on'),2600)};\nconst banner=t=>{const b=$('#banner');b.textContent=t||'';b.style.display=t?'block':'none'};\nconst locName=id=>S.loc.find(l=>l.id===id)?.nome||'';\nconst etaTxt=l=>l&&l.tipo==='format'?(l.eta_min?l.eta_min+'+':'età da indicare'):'';\nconst serOrd=()=>[...S.ser].sort((a,b)=>(a.data||'').localeCompare(b.data||''));\nconst R=(s,id)=>{const x=(s.ris||{})[id];return typeof x==='number'?{b:x,t:0,e:0}:{b:+(x&&x.b)||0,t:+(x&&x.t)||0,e:+(x&&x.e)||0}};\nconst add=(a,r)=>(a.b+=r.b,a.t+=r.t,a.e=(a.e||0)+(r.e||0),a);\nconst EUR=new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0});\nconst EUR2=new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',minimumFractionDigits:2});\nconst eur=c=>((c||0)%100?EUR2:EUR).format((c||0)/100); // incasso salvato in centesimi\nconst cent=v=>{const n=parseFloat(String(v||'').replace(/\\s|€/g,'').replace(/\\.(?=\\d{3}(\\D|$))/g,'').replace(',','.'));return Number.isFinite(n)&&n>0?Math.round(n*100):0};\n/* PR \"a segno\": fa più del migliore dei suoi risultati nelle 2 serate precedenti dello stesso format\n   (con meno serate precedenti si confronta con quelle che ci sono; alla prima basta almeno 1).\n   Format a persone: TicketSMS + tavoli; format a incasso: incasso. */\nconst valSegno=(s,id)=>{const r=R(s,id);return misuraDi(s.fmt)==='incasso'?r.e:r.b+r.t};\nfunction calcSegno(){const g={},m=new Map();for(const s of serOrd())(g[s.fmt||'']||=[]).push(s);\n  for(const l of Object.values(g))l.forEach((s,i)=>{const prev=l.slice(Math.max(0,i-2),i),set=new Set();\n    for(const id of Object.keys(s.ris||{})){const v=valSegno(s,id),best=Math.max(0,...prev.map(p=>valSegno(p,id)));if(v>best)set.add(id)}m.set(s.id,set)});\n  return m}\nconst segno=s=>(S.segno&&S.segno.get(s.id))||new Set();\nconst misuraDi=fid=>S.loc.find(l=>l.id===fid)?.misura==='incasso'?'incasso':'persone';\nconst vend=(id,ser)=>ser.reduce((a,s)=>add(a,R(s,id)),{b:0,t:0});\nconst team=(id,ser)=>{const a=vend(id,ser);for(const c of figli(id))add(a,team(c.id,ser));return a};\nconst sumSer=s=>Object.keys(s.ris||{}).reduce((a,id)=>add(a,R(s,id)),{b:0,t:0,e:0});\nconst BT=v=>`<b>${v.b}</b> bigl. · <b>${v.t}</b> tav.${v.e?` · <b>${eur(v.e)}</b>`:''}`;\nconst view=()=>{const h=location.hash.slice(1);return h.startsWith('persona-')?'persona':['archivio','struttura','serate','report','punti','accessi'].includes(h)?h:'archivio'};\n\n/* ---------- grafici ---------- */\nconst bars=(rows)=>{if(!rows.length)return '<p class=\"empty\">Nessun dato</p>';const m=Math.max(...rows.map(r=>r[1]),1);\n  return rows.map(([k,v])=>`<div class=\"bar\"><span class=\"bl\" title=\"${esc(k)}\">${esc(k)}</span><span class=\"bt\"><i style=\"width:${(v/m*100).toFixed(1)}%\"></i></span><b>${v}</b></div>`).join('')};\nconst gruppo=(f,sortKey)=>{const m=new Map();let nd=0;for(const p of S.pr){const v=String(p[f]??'').trim();if(!v){nd++;continue}m.set(v,(m.get(v)||0)+1)}\n  let r=[...m];r.sort(sortKey?(a,b)=>a[0].localeCompare(b[0]):(a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'it'));\n  if(!sortKey&&r.length>12){const alt=r.slice(11).reduce((t,x)=>t+x[1],0);r=r.slice(0,11).concat([['Altre',alt]])}\n  if(nd)r.push(['Non indicato',nd]);return r};\nconst colChart=(id,pts)=>{S.charts[id]=pts;return `<div class=\"fig${id[0]==='p'?' sm':''}\"><svg data-c=\"${id}\" role=\"img\" aria-label=\"Grafico a colonne\"></svg></div>`};\n/* grafico a colonne raggruppate: per ogni serata TicketSMS, tavoli e (se c'è) incasso, con l'asse € a destra */\nconst groupChart=(id,data)=>{S.charts[id]={grp:true,...data};return `<div class=\"fig\"><svg data-c=\"${id}\" role=\"img\" aria-label=\"Grafico a colonne raggruppate\"></svg></div>`};\nconst tick=m=>{const st=Math.max(1,Math.ceil(m/4/(m>20?5:1))*(m>20?5:1));return {st,top:Math.ceil(Math.max(1,m)/st)*st}};\nfunction drawGrp(s,g){const W=s.clientWidth,H=s.clientHeight,pts=g.pts,se=g.serie;\n  if(!pts.length){s.innerHTML=`<text x=\"${W/2}\" y=\"${H/2}\" text-anchor=\"middle\">Nessuna serata con risultati</text>`;return}\n  // scale differenziate: ogni misura ha la sua scala (la colonna più alta di ogni colore arriva in cima); sulle colonne i valori reali\n  const L=8,Rm=8,T=18,B=24,iw=W-L-Rm,ih=H-T-B,n=pts.length,k=se.length;\n  const tops=se.map((x,j)=>Math.max(1,...pts.map(p=>p.v[j])));\n  const bw=iw/n,w=Math.max(3,Math.min(18,bw*.8/k)),every=Math.ceil(n/Math.max(1,Math.floor(iw/(W<520?56:48))));let o='';\n  for(let i=0;i<=4;i++){const y=T+ih-i/4*ih;o+=`<line x1=\"${L}\" x2=\"${W-Rm}\" y1=\"${y}\" y2=\"${y}\" stroke=\"var(--line)\"/>`}\n  pts.forEach((p,i)=>{const x0=L+i*bw+(bw-k*w)/2;se.forEach((x,j)=>{const v=p.v[j],h=v/tops[j]*ih,xx=x0+j*w,y=T+ih-h;\n      o+=`<rect x=\"${xx}\" y=\"${y}\" width=\"${w-1}\" height=\"${Math.max(h,v?2:0)}\" rx=\"2\" fill=\"${x.c}\"><title>${esc(p.t)} · ${x.n}: ${x.eur?v+' €':v}</title></rect>`;\n      if(v&&w>=10)o+=`<text class=\"v\" x=\"${xx+w/2-.5}\" y=\"${y-4}\" text-anchor=\"middle\" style=\"font-size:10px\">${x.eur?v+'€':v}</text>`});\n    if(i%every===0)o+=`<text x=\"${L+i*bw+bw/2}\" y=\"${H-7}\" text-anchor=\"middle\">${esc(p.l)}</text>`});\n  s.innerHTML=o}\nconst draw=()=>{for(const s of document.querySelectorAll('svg[data-c]')){const cg=S.charts[s.dataset.c];if(cg&&cg.grp){if(s.clientWidth)drawGrp(s,cg);continue}const pts=cg||[];const W=s.clientWidth,H=s.clientHeight;if(!W)continue;\n  if(!pts.length){s.innerHTML=`<text x=\"${W/2}\" y=\"${H/2}\" text-anchor=\"middle\">Nessuna serata con risultati</text>`;continue}\n  const col=/^[pq]?t$/.test(s.dataset.c)?'var(--yel)':/^[pq]?e$/.test(s.dataset.c)?'var(--inc)':'var(--red)';const L=32,R=6,T=16,B=24,iw=W-L-R,ih=H-T-B,n=pts.length,max=Math.max(1,...pts.map(p=>p.v));\n  const step=Math.max(1,Math.ceil(max/4/(max>20?5:1))*(max>20?5:1));const top=Math.ceil(max/step)*step;\n  const bw=iw/n,w=Math.min(52,bw*.7),every=Math.ceil(n/Math.max(1,Math.floor(iw/(W<520?56:48))));let g='';\n  for(let v=0;v<=top;v+=step){const y=T+ih-v/top*ih;g+=`<line x1=\"${L}\" x2=\"${W-R}\" y1=\"${y}\" y2=\"${y}\" stroke=\"var(--line)\"/><text x=\"${L-6}\" y=\"${y+4}\" text-anchor=\"end\">${v}</text>`}\n  pts.forEach((p,i)=>{const h=p.v/top*ih,x=L+i*bw+(bw-w)/2,y=T+ih-h;\n    if(p.segs){let yy=T+ih;for(const sg of p.segs){if(!sg.v)continue;const hh=sg.v/top*ih;yy-=hh;g+=`<rect x=\"${x}\" y=\"${yy}\" width=\"${w}\" height=\"${hh}\" fill=\"${sg.c}\" stroke=\"var(--panel)\" stroke-width=\"1\"><title>${esc(p.t)} · ${esc(sg.n)}: ${sg.v}</title></rect>`}}\n    else g+=`<rect x=\"${x}\" y=\"${y}\" width=\"${w}\" height=\"${Math.max(h,p.v?2:0)}\" rx=\"3\" fill=\"${p.v?col:'var(--line)'}\"><title>${esc(p.t)}: ${p.v}</title></rect>`;\n    if(bw>=24&&p.v)g+=`<text class=\"v\" x=\"${x+w/2}\" y=\"${y-5}\" text-anchor=\"middle\">${p.v}</text>`;\n    if(i%every===0)g+=`<text x=\"${x+w/2}\" y=\"${H-7}\" text-anchor=\"middle\">${esc(p.l)}</text>`});\n  s.innerHTML=g}};\nconst ro=new ResizeObserver(draw);ro.observe($('#main'));\n\n/* ---------- archivio ---------- */\nfunction filtrati(){const q=norm(S.q);return S.pr.filter(p=>(!S.fR||p.ruolo===S.fR)&&(!S.fS||p.scuola===S.fS)&&(!S.fZ||p.zona===S.fZ)&&\n  (!q||norm([p.nome,p.cognome,p.scuola,p.zona,p.tel,p.note].join(' ')).includes(q))).map(p=>({p,v:vend(p.id,S.ser)})).sort((A,B)=>{const {k,d}=S.so,a=A.p,b=B.p;\n  const key=x=>k==='nome'?nome(x.p):k==='ruolo'?ORD[x.p.ruolo]:k==='parent'?(x.p.parent?nome(byId(x.p.parent)):''):k==='b'||k==='t'?x.v[k]:(x.p[k]??'');\n  const ka=key(A),kb=key(B);let c=typeof ka==='number'&&typeof kb==='number'?ka-kb:String(ka).localeCompare(String(kb),'it',{numeric:true});\n  if((ka===''||ka==null)!==(kb===''||kb==null))return ka===''||ka==null?1:-1;return c*d||sortNome(a,b)})}\nfunction righe(){const l=filtrati();\n  if(!l.length)return `<tr><td colspan=\"9\"><p class=\"empty\">${S.pr.length?'Nessuno corrisponde ai filtri.':'Archivio vuoto: aggiungi il primo PR.'}</p></td></tr>`;\n  return l.map(({p,v})=>`<tr><td><button class=\"link\" data-pg=\"${p.id}\">${esc(nome(p))}</button>${p.note?`<span class=\"note\" title=\"${esc(p.note)}\">${esc(p.note)}</span>`:''}</td>\n  <td><span class=\"tag ${p.ruolo}\">${RUOLI[p.ruolo]||'PR'}</span></td><td>${p.parent?esc(nome(byId(p.parent))):`<span class=\"note\">${p.ruolo==='staff'?'Vertice':'Singolo'}</span>`}</td>\n  <td class=\"n\">${esc(p.anno||'')}</td><td>${esc(p.scuola||'')}</td><td>${esc(p.zona||'')}</td><td class=\"n\">${esc(p.tel||'')}</td><td class=\"n\">${v.b||''}</td><td class=\"n\">${v.t||''}</td></tr>`).join('')}\nconst opts=(f)=>[...new Set(S.pr.map(p=>String(p[f]||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'it'));\nfunction vArchivio(){const c=k=>S.pr.filter(p=>p.ruolo===k).length;\n  const sel=(id,cur,list,lab)=>`<label>${lab}<select id=\"${id}\"><option value=\"\">Tutte</option>${list.map(v=>`<option ${v===cur?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;\n  return `<div class=\"top\"><div class=\"sp\"><h2>${S.me.ruolo==='admin'?'Archivio PR':'Il tuo ramo'}</h2><p class=\"sub\">${S.me.ruolo==='admin'?'Tutte le persone della rete.':'Le persone collegate a te. I nuovi PR vanno collegati a te o a un tuo Capo PR.'} Basta il nome o il cognome, il resto è facoltativo.</p></div><button class=\"pri\" data-new=\"1\">Nuovo PR</button></div>\n  <div class=\"kpis\"><div class=\"kpi\"><b>${S.pr.length}</b><span>persone in archivio</span></div><div class=\"kpi\"><b>${c('staff')}</b><span>capi staff</span></div>\n  <div class=\"kpi\"><b>${c('capo')}</b><span>capi PR</span></div><div class=\"kpi\"><b>${c('pr')}</b><span>PR</span></div>\n  <div class=\"kpi\"><b>${S.pr.filter(p=>!p.parent&&p.ruolo!=='staff').length}</b><span>senza superiore</span></div></div>\n  <div class=\"grid3\"><div class=\"card\"><h3>Anno di nascita</h3><div class=\"bars\">${bars(gruppo('anno',1))}</div></div><div class=\"card\"><h3>Zone</h3><div class=\"bars\">${bars(gruppo('zona'))}</div></div><div class=\"card\"><h3>Scuole</h3><div class=\"bars\">${bars(gruppo('scuola'))}</div></div></div>\n  <div class=\"filters\"><label>Cerca<input id=\"q\" type=\"search\" value=\"${esc(S.q)}\" placeholder=\"Nome, scuola, telefono, note…\"></label>\n  <label>Ruolo<select id=\"fR\"><option value=\"\">Tutti</option>${Object.entries(RUOLI).map(([k,v])=>`<option value=\"${k}\" ${k===S.fR?'selected':''}>${v}</option>`).join('')}</select></label>\n  ${sel('fS',S.fS,opts('scuola'),'Scuola')}${sel('fZ',S.fZ,opts('zona'),'Zona')}<button id=\"clr\">Azzera</button></div>\n  <p class=\"note\" id=\"cnt\" style=\"margin:0 0 6px\"></p><div class=\"tbl\"><table class=\"stack\"><thead><tr>${[['nome','Nome'],['ruolo','Ruolo'],['parent','Superiore'],['anno','Anno','n'],['scuola','Scuola'],['zona','Zona'],['tel','Telefono','n'],['b','Biglietti','n'],['t','Tavoli','n']].map(([k,t,c])=>`<th data-so=\"${k}\" class=\"${c||''} ${S.so.k===k?'on':''}\">${t}${S.so.k===k?(S.so.d>0?' ↑':' ↓'):''}</th>`).join('')}</tr></thead><tbody id=\"tb\">${righe()}</tbody></table></div>`}\n\n/* ---------- struttura ---------- */\nfunction vStruttura(){const ser=S.ser,T=id=>`<span class=\"tot\">personali ${BT(vend(id,ser))}</span>`;\n  const leaves=list=>list.length?`<div class=\"leaves\">${list.sort(sortNome).map(p=>{const v=vend(p.id,ser);return `<span class=\"leaf\"><button class=\"link\" data-pg=\"${p.id}\">${esc(nome(p))}</button><span title=\"biglietti · tavoli${v.e?' · incasso':''}\">${v.b} · ${v.t}${v.e?' · '+eur(v.e):''}</span></span>`}).join('')}</div>`:'';\n  const capo=c=>{const pr=figli(c.id);return `<div class=\"c\"><div class=\"nh\"><span class=\"tag capo\">Capo PR</span><button class=\"link\" data-pg=\"${c.id}\">${esc(nome(c))}</button><span class=\"sp\"></span>${T(c.id)}<span class=\"tot\">gruppo ${BT(team(c.id,ser))} · ${pr.length} PR</span></div>${leaves(pr)||'<p class=\"empty\">Nessun PR collegato</p>'}</div>`};\n  const top=p=>!p.parent||!byId(p.parent);\n  const staff=S.pr.filter(p=>p.ruolo==='staff'&&top(p)).sort(sortNome);\n  const cS=S.pr.filter(p=>p.ruolo==='capo'&&top(p)).sort(sortNome),soli=S.pr.filter(p=>p.ruolo==='pr'&&top(p));\n  const nodo=s=>{const f=figli(s.id),ss=f.filter(p=>p.ruolo==='staff').sort(sortNome),cp=f.filter(p=>p.ruolo==='capo').sort(sortNome),dir=f.filter(p=>p.ruolo==='pr');\n    return `<details class=\"node\" open><summary class=\"nh\"><span class=\"tag staff\">Capo staff</span><button class=\"link\" data-pg=\"${s.id}\">${esc(nome(s))}</button><span class=\"sp\"></span>${T(s.id)}<span class=\"tot\">staff ${BT(team(s.id,ser))} · ${f.length} collegati</span></summary>\n    ${ss.map(nodo).join('')}${cp.map(capo).join('')}${dir.length?`<div class=\"c\"><div class=\"nh\"><b>PR diretti</b><span class=\"sp\"></span><span class=\"tot\">${dir.length} PR</span></div>${leaves(dir)}</div>`:''}${!f.length?'<p class=\"empty\">Nessuno collegato</p>':''}</details>`};\n  let h=`<div class=\"top\"><div class=\"sp\"><h2>Struttura dello staff</h2><p class=\"sub\">Capo staff (anche sotto un altro Capo staff) → Capo PR → PR. \"Gruppo\" e \"staff\" sommano tutto il ramo; sulle etichette biglietti · tavoli.</p></div><button class=\"pri\" data-new=\"1\">Nuova persona</button></div><div class=\"tree\">`;\n  if(!S.pr.length)h+='<p class=\"empty\">Nessuno in archivio.</p>';\n  h+=staff.map(nodo).join('');\n  if(cS.length)h+=`<details class=\"node\" open style=\"border-left-color:var(--yel)\"><summary class=\"nh\"><b>Capi PR senza capo staff</b></summary>${cS.map(capo).join('')}</details>`;\n  if(soli.length)h+=`<details class=\"node\" open style=\"border-left-color:var(--line)\"><summary class=\"nh\"><b>PR singoli</b><span class=\"sp\"></span><span class=\"tot\">${soli.length} PR</span></summary>${leaves(soli)}</details>`;\n  return h+'</div>'}\n\n/* ---------- serate ---------- */\nfunction vSerate(){const l=serOrd().reverse();\n  const chip=x=>`<span class=\"leaf\"><button class=\"link\" data-el=\"${x.id}\" title=\"Modifica\">${esc(x.nome)}</button><span ${x.tipo==='format'&&!x.eta_min?'style=\"color:var(--red)\"':''}>${x.tipo==='format'?'format · '+etaTxt(x)+(x.misura==='incasso'?' · a incasso':''):'locale'}</span><button class=\"ghost\" data-dl=\"${x.id}\" aria-label=\"Elimina ${esc(x.nome)}\">×</button></span>`;\n  return `<div class=\"top\"><div class=\"sp\"><h2>Serate</h2><p class=\"sub\">Inserisci biglietti TicketSMS e tavoli di ogni PR. Chi fa 0 in entrambi non viene registrato.</p></div><button class=\"pri\" data-ns=\"1\">Nuova serata</button></div>\n  <div class=\"card\" style=\"margin-bottom:12px\"><h3>Locali e format</h3><div class=\"chips\">${S.loc.length?[...S.loc].sort((a,b)=>a.tipo.localeCompare(b.tipo)||a.nome.localeCompare(b.nome,'it')).map(chip).join(''):'<p class=\"empty\">Aggiungi i locali e i format: ognuno avrà la sua sezione nei report.</p>'}</div>\n  <div class=\"row\"><input id=\"lN\" placeholder=\"Nome locale o format\" style=\"flex:2 1 200px;width:auto\"><select id=\"lT\" style=\"flex:1 1 120px;width:auto\"><option value=\"locale\">Locale</option><option value=\"format\">Format</option></select><input id=\"lE\" type=\"number\" inputmode=\"numeric\" min=\"6\" max=\"99\" placeholder=\"Età minima (es. 14)\" style=\"flex:1 1 150px;width:auto\" hidden><select id=\"lMis\" style=\"flex:1 1 150px;width:auto\" hidden><option value=\"persone\">Si misura a persone</option><option value=\"incasso\">Si misura a incasso</option></select><button id=\"lA\">Aggiungi</button></div><p class=\"msg\" id=\"lM\"></p></div>\n  <div class=\"tbl\"><table class=\"stack\"><thead><tr><th>Data</th><th>Serata</th><th>Locale</th><th>Format</th><th class=\"n\">PR attivi</th><th class=\"n\">A segno</th><th class=\"n\">Biglietti</th><th class=\"n\">Tavoli</th><th class=\"n\">Incasso tavoli</th></tr></thead><tbody>\n  ${l.length?l.map(s=>{const v=sumSer(s);return `<tr><td class=\"n\" style=\"text-align:left\">${fmtD(s.data)}</td><td><button class=\"link\" data-es=\"${s.id}\">${esc(s.nome||'Serata')}</button></td><td>${esc(locName(s.loc))}</td><td>${esc(locName(s.fmt))}</td><td class=\"n\">${Object.keys(s.ris||{}).length}</td><td class=\"n\">${segno(s).size}</td><td class=\"n\">${v.b}</td><td class=\"n\">${v.t}</td><td class=\"n\">${v.e?eur(v.e):''}</td></tr>`}).join(''):'<tr><td colspan=\"9\"><p class=\"empty\">Nessuna serata inserita.</p></td></tr>'}</tbody></table></div>`}\n\n/* ---------- report ---------- */\nfunction classifica(ser,loc,fm){const k=S.clT||'pr',m1=n=>n.toFixed(1).replace('.',',');\n  const inc=ser.some(s=>sumSer(s).e>0);let key=S.clS||'tot';if(!inc&&(key==='e'||key==='emedia'))key='tot';\n  const righe=S.pr.filter(p=>p.ruolo===k).map(p=>{let b=0,t=0,e=0,n=0,ne=0;for(const s of ser){const v=k==='pr'?R(s,p.id):team(p.id,[s]);b+=v.b;t+=v.t;e+=v.e||0;if(v.b+v.t>=1)n++;if(v.e>0)ne++}\n    return {p,b,t,e,tot:b+t,n,ne,media:n?(b+t)/n:0,emedia:ne?e/ne:0}}).filter(x=>x.tot>=1||x.e>0).sort((a,b)=>b[key]-a[key]||b.tot-a.tot||sortNome(a.p,b.p));\n  const tab=(v,l)=>`<button data-cl=\"${v}\" class=\"${k===v?'on':''}\">${l}</button>`;\n  const th=(v,l)=>`<th class=\"n ${key===v?'on':''}\">${l}</th>`;\n  return `<div class=\"card\" style=\"margin-bottom:12px\"><div class=\"row\" style=\"margin-bottom:8px\"><h3 style=\"margin:0\">Classifica</h3>\n  <div class=\"tabs\" style=\"margin:0\">${tab('staff','Capi staff')}${tab('capo','Capi PR')}${tab('pr','PR')}</div><span class=\"sp\"></span>\n  <label style=\"display:flex;gap:6px;align-items:center\">Ordina per <select id=\"clS\" style=\"width:auto\">${[['tot','Totale persone'],['b','TicketSMS'],['t','Tavoli'],['media','Media persone']].concat(inc?[['e','Incasso tavoli'],['emedia','Incasso medio']]:[]).map(([v,l])=>`<option value=\"${v}\" ${v===key?'selected':''}>${l}</option>`).join('')}</select></label>\n  <label style=\"display:flex;gap:6px;align-items:center\">Serate <select id=\"clF\" style=\"width:auto\"><option value=\"all\">Tutte</option>${loc.length?`<optgroup label=\"Locali\">${loc.map(l=>`<option value=\"${l.id}\" ${S.rep===l.id?'selected':''}>${esc(l.nome)}</option>`).join('')}</optgroup>`:''}${fm.length?`<optgroup label=\"Format\">${fm.map(l=>`<option value=\"${l.id}\" ${S.rep===l.id?'selected':''}>${esc(l.nome)}${l.eta_min?' · '+l.eta_min+'+':''}</option>`).join('')}</optgroup>`:''}</select></label></div>\n  <p class=\"note\" style=\"margin:0 0 8px\">${k==='pr'?'PR: solo i risultati personali.':`${k==='staff'?'Capi staff':'Capi PR'}: personali + tutto il loro gruppo.`} Totale persone = TicketSMS + tavoli; media = totale persone diviso le serate con almeno 1 persona.${inc?' Incasso medio = incasso tavoli diviso le serate con incasso.':''}</p>\n  ${righe.length?`<div class=\"tbl s\"><table><thead><tr><th class=\"n\">#</th><th>Nome</th><th class=\"n\">Serate</th>${th('b','TicketSMS')}${th('t','Tavoli')}${th('tot','Totale persone')}${th('media','Media persone')}${inc?th('e','Incasso tavoli')+th('emedia','Incasso medio'):''}</tr></thead><tbody>\n  ${righe.map((x,i)=>`<tr><td class=\"n\">${i+1}</td><td><button class=\"link\" data-pg=\"${x.p.id}\">${esc(nome(x.p))}</button>${x.p.parent&&byId(x.p.parent)?`<span class=\"note i\">${esc(nome(byId(x.p.parent)))}</span>`:''}</td><td class=\"n\">${x.n}</td><td class=\"n\">${x.b}</td><td class=\"n\">${x.t}</td><td class=\"n\"><b>${x.tot}</b></td><td class=\"n\">${m1(x.media)}</td>${inc?`<td class=\"n\"><b>${x.e?eur(x.e):''}</b></td><td class=\"n\">${x.ne?eur(x.emedia):''}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<p class=\"empty\">Nessun risultato in queste serate.</p>'}</div>`}\nfunction vReport(){const loc=S.loc.filter(l=>l.tipo!=='format').sort((a,b)=>a.nome.localeCompare(b.nome,'it')),fm=S.loc.filter(l=>l.tipo==='format').sort((a,b)=>a.nome.localeCompare(b.nome,'it'));\n  if(S.rep!=='all'&&!S.loc.some(l=>l.id===S.rep))S.rep='all';\n  const tb=(k,t)=>`<button data-rp=\"${k}\" class=\"${S.rep===k?'on':''}\">${esc(t)}</button>`;\n  const ser=serOrd().filter(s=>S.rep==='all'||s.loc===S.rep||s.fmt===S.rep);\n  const titolo=S.rep==='all'?'Tutte le serate':locName(S.rep);\n  const tot=ser.reduce((a,s)=>add(a,sumSer(s)),{b:0,t:0,e:0}),inc=tot.e>0,serInc=ser.filter(s=>sumSer(s).e>0).length;\n  const stat=new Map();for(const s of ser)for(const id of Object.keys(s.ris||{})){const r=R(s,id);if(r.b<1&&r.t<1&&!r.e)continue;const o=stat.get(id)||{b:0,t:0,e:0,n:0,max:0};o.b+=r.b;o.t+=r.t;o.e+=r.e;o.n++;o.max=Math.max(o.max,r.b+r.t);stat.set(id,o)}\n  const cls=[...stat].sort((a,b)=>b[1].b-a[1].b||b[1].t-a[1].t);\n  const rami=S.pr.filter(p=>p.ruolo!=='pr'&&figli(p.id).length).map(p=>[p,team(p.id,ser)]).filter(x=>x[1].b||x[1].t||x[1].e).sort((a,b)=>(b[1].b+b[1].t)-(a[1].b+a[1].t)||b[1].e-a[1].e);\n  const trendL=S.pr.map(p=>[p,team(p.id,ser)]).filter(([,v])=>v.b||v.t||v.e).sort((a,b)=>ORD[a[0].ruolo]-ORD[b[0].ruolo]||sortNome(a[0],b[0]));\n  const trendV=new Map(trendL.map(([p,v])=>[p.id,v]));\n  if(S.repPr&&!trendV.has(S.repPr))S.repPr='';const pSel=S.repPr||cls[0]?.[0]||trendL[0]?.[0].id||'';\n  const pt=(s,v)=>({l:fmtD(s.data).slice(0,5),t:`${fmtD(s.data)} ${s.nome||''}`,v});\n  const best=ser.reduce((b,s)=>{const v=sumSer(s).b;return !b||v>b.v?{v,s}:b},null);\n  const m1=n=>n.toFixed(1).replace('.',',');\n  return `<div class=\"top\"><div class=\"sp\"><h2>Report risultati</h2><p class=\"sub\">Un PR conta in una serata solo se ha almeno 1 biglietto, 1 tavolo o un incasso. Persone ed euro non si sommano mai tra loro.</p></div></div>\n  <div class=\"tabs\">${tb('all','Complessivo')}${loc.length?'<small>Locali</small>':''}${loc.map(l=>tb(l.id,l.nome)).join('')}${fm.length?'<small>Format</small>':''}${fm.map(l=>tb(l.id,l.nome+(l.eta_min?' · '+l.eta_min+'+':'')+(l.misura==='incasso'?' · €':''))).join('')}</div>\n  <h3 style=\"font-size:18px\">${esc(titolo)}</h3>\n  <div class=\"kpis\"><div class=\"kpi\"><b>${ser.length}</b><span>serate</span></div><div class=\"kpi\"><b>${tot.b}</b><span>biglietti TicketSMS</span></div>\n  <div class=\"kpi\"><b>${tot.t}</b><span>tavoli</span></div><div class=\"kpi\"><b>${ser.length?m1((tot.b+tot.t)/ser.length):'0'}</b><span>persone medie a serata (TicketSMS + tavoli)</span></div>\n  <div class=\"kpi\"><b>${new Set(ser.flatMap(s=>[...segno(s)])).size}</b><span>PR andati a segno almeno una volta</span></div>\n  <div class=\"kpi\"><b>${best?best.v:0}</b><span>biglietti nella serata migliore${best?' · '+fmtD(best.s.data):''}</span></div>\n  ${inc?`<div class=\"kpi\" style=\"border-top-color:var(--or)\"><b>${eur(tot.e)}</b><span>incasso tavoli</span></div><div class=\"kpi\" style=\"border-top-color:var(--or)\"><b>${eur(serInc?tot.e/serInc:0)}</b><span>incasso medio a serata (serate con incasso)</span></div>`:''}</div>\n  <div class=\"grid3\"><div class=\"card\"><h3>Biglietti per serata</h3>${colChart('b',ser.map(s=>pt(s,sumSer(s).b)))}</div>\n  <div class=\"card\"><h3>Tavoli per serata</h3>${colChart('t',ser.map(s=>pt(s,sumSer(s).t)))}</div>\n  <div class=\"card\"><h3>PR andati a segno per serata</h3><p class=\"note\" style=\"margin:-4px 0 4px\">Hanno superato il loro miglior risultato delle 2 serate precedenti dello stesso format</p>${colChart('a',ser.map(s=>pt(s,segno(s).size)))}</div>\n  ${inc?`<div class=\"card\"><h3>Incasso tavoli per serata (€)</h3>${colChart('e',ser.map(s=>pt(s,Math.round(sumSer(s).e/100))))}</div>`:''}</div>\n  ${classifica(ser,loc,fm)}\n  <div class=\"grid2\">\n  <div class=\"card\"><h3>Trend di un PR</h3><label>Persona (risultati personali + di tutti quelli sotto di lui)<select id=\"rpP\">${trendL.map(([p])=>`<option value=\"${p.id}\" ${p.id===pSel?'selected':''}>${esc(nome(p))}${p.ruolo!=='pr'?' · '+RUOLI[p.ruolo]:''}</option>`).join('')||'<option>Nessuno</option>'}</select></label>\n  ${(()=>{const hasE=!!(pSel&&trendV.get(pSel)?.e),serie=[{n:'TicketSMS',c:'var(--red)'},{n:'Tavoli',c:'var(--yel)'}].concat(hasE?[{n:'Incasso tavoli',c:'var(--inc)',eur:true}]:[]);\n    const sw=c=>`<i style=\"width:10px;height:10px;border-radius:3px;background:${c};display:inline-block;margin-right:4px\"></i>`;\n    return `<div class=\"row\" style=\"gap:12px;margin:10px 0 0;font-size:12.5px;color:var(--mute)\">${serie.map(x=>`<span>${sw(x.c)}${x.n}</span>`).join('')}<span>· ogni colore ha la sua scala: la colonna più alta di ogni colore è il massimo di quella misura; i numeri sono i valori reali</span></div>`\n      +groupChart('pg',{serie,pts:pSel?ser.map(s=>{const r=team(pSel,[s]);return {...pt(s,0),v:[r.b,r.t].concat(hasE?[Math.round(r.e/100)]:[])}}):[]})})()}</div></div>\n  <div class=\"card\"><h3>Totale per ramo dello staff</h3>${rami.length?`<div class=\"tbl s\"><table><thead><tr><th>Ramo</th><th class=\"n\">Biglietti</th><th class=\"n\">Tavoli</th>${inc?'<th class=\"n\">Incasso tavoli</th>':''}</tr></thead><tbody>${rami.map(([p,v])=>`<tr><td><button class=\"link\" data-pg=\"${p.id}\">${esc(nome(p))}</button><span class=\"note i\">${RUOLI[p.ruolo]} · ${figli(p.id).length} collegati</span></td><td class=\"n\"><b>${v.b}</b></td><td class=\"n\">${v.t}</td>${inc?`<td class=\"n\">${v.e?eur(v.e):''}</td>`:''}</tr>`).join('')}</tbody></table></div>`:'<p class=\"empty\">Nessun ramo con risultati.</p>'}</div>`}\n\n\n/* ---------- pagina persona ---------- */\nconst PAL=['#e3301c','#ff8a1f','#2f7fd8','#1f9e6e','#ffbf1f','#8a4fd1','#d6337f','#4fb3a9','#a0522d','#6b7a8f','#b38f00','#3b3b98','#ff6f91','#7aa83a','#c45c00','#5e7ce2'];\nfunction scopeTabs(){const loc=S.loc.filter(l=>l.tipo!=='format').sort((a,b)=>a.nome.localeCompare(b.nome,'it')),fm=S.loc.filter(l=>l.tipo==='format').sort((a,b)=>a.nome.localeCompare(b.nome,'it'));\n  if(S.rep!=='all'&&!S.loc.some(l=>l.id===S.rep))S.rep='all';\n  const tb=(k,t)=>`<button data-rp=\"${k}\" class=\"${S.rep===k?'on':''}\">${esc(t)}</button>`;\n  return `<div class=\"tabs\">${tb('all','Complessivo')}${loc.length?'<small>Locali</small>':''}${loc.map(l=>tb(l.id,l.nome)).join('')}${fm.length?'<small>Format</small>':''}${fm.map(l=>tb(l.id,l.nome+(l.eta_min?' · '+l.eta_min+'+':'')+(l.misura==='incasso'?' · €':''))).join('')}</div>`}\nfunction vPersona(){const id=location.hash.slice(9),p=byId(id);\n  if(!p)return `<div class=\"top\"><div class=\"sp\"><h2>Persona non trovata</h2><p class=\"sub\">Potrebbe essere stata eliminata.</p></div><a class=\"btn\" href=\"#archivio\" style=\"display:inline-flex;align-items:center;text-decoration:none\">Torna all'archivio</a></div>`;\n  const ser=serOrd().filter(s=>S.rep==='all'||s.loc===S.rep||s.fmt===S.rep);\n  const lab=s=>({l:fmtD(s.data).slice(0,5),t:`${fmtD(s.data)} ${s.nome||''}`});\n  /* segmenti: risultati personali + collegati (per un capo staff, i Capi PR valgono con tutto il gruppo) */\n  const segs=[{n:'Personali',id:null,ruolo:p.ruolo,f:s=>R(s,id)}];\n  const f=figli(id).sort((a,b)=>ORD[a.ruolo]-ORD[b.ruolo]||sortNome(a,b));\n  for(const c of f)segs.push({n:nome(c)+(c.ruolo!=='pr'?' (gruppo)':''),id:c.id,ruolo:c.ruolo,f:c.ruolo!=='pr'?(s=>team(c.id,[s])):(s=>R(s,c.id))});\n  for(const sg of segs){sg.tot=ser.reduce((a,s)=>add(a,sg.f(s)),{b:0,t:0,e:0});sg.ser=ser.filter(s=>{const r=sg.f(s);return r.b||r.t||r.e}).length}\n  const attivi=segs.filter(sg=>sg.tot.b||sg.tot.t||sg.tot.e);let ci=0;for(const sg of segs)sg.c=sg.id===null?'var(--ink)':(sg.tot.b||sg.tot.t||sg.tot.e)?PAL[ci++%PAL.length]:'var(--line)';\n  const tot=segs.reduce((a,sg)=>add(a,{...sg.tot}),{b:0,t:0,e:0}),inc=tot.e>0;\n  const perSer=ser.map(s=>segs.reduce((a,sg)=>add(a,sg.f(s)),{b:0,t:0,e:0}));\n  const best=ser.reduce((b,s,i)=>!b||perSer[i].b>b.v?{v:perSer[i].b,s}:b,null);\n  const conRis=perSer.filter(v=>v.b||v.t).length;\n  const capo=p.ruolo!=='pr'&&f.length;\n  const m1=n=>n.toFixed(1).replace('.',',');\n  const chart=(k,key)=>capo?colChart(k,ser.map(s=>{const sg=attivi.map(x=>({n:x.n,c:x.c,v:key==='e'?Math.round((x.f(s).e||0)/100):x.f(s)[key]}));return {...lab(s),v:sg.reduce((a,x)=>a+x.v,0),segs:sg}})):colChart(k,ser.map(s=>({...lab(s),v:key==='e'?Math.round(R(s,id).e/100):R(s,id)[key]})));\n  const info=[['Anno',p.anno],['Scuola',p.scuola],['Zona',p.zona],['Telefono',p.tel]].filter(x=>x[1]);\n  const legend=capo?`<div class=\"leaves\" style=\"margin:0 0 8px\">${attivi.map(sg=>`<span class=\"leaf\" style=\"padding-left:6px\"><i style=\"width:10px;height:10px;border-radius:3px;background:${sg.c};display:inline-block\"></i>${sg.id?`<button class=\"link\" data-pg=\"${sg.id}\">${esc(sg.n)}</button>`:`<b>${esc(sg.n)}</b>`}<span>${sg.tot.b} · ${sg.tot.t}${sg.tot.e?' · '+eur(sg.tot.e):''}</span></span>`).join('')||'<p class=\"empty\">Nessun risultato in queste serate.</p>'}</div>`:'';\n  return `<div class=\"top\"><div class=\"sp\"><p class=\"sub\" style=\"margin:0 0 4px\"><button class=\"link\" data-back=\"1\" style=\"font-weight:600\">← Indietro</button></p>\n  <h2>${esc(nome(p))} <span class=\"tag ${p.ruolo}\" style=\"vertical-align:middle;font-size:13px\">${RUOLI[p.ruolo]}</span></h2>\n  <p class=\"sub\">${p.parent?`Sotto <button class=\"link\" data-pg=\"${p.parent}\">${esc(nome(byId(p.parent)))}</button>`:p.ruolo==='staff'?'Vertice dello staff':'Senza superiore'}${info.map(([k,v])=>` · ${k} <b style=\"color:var(--ink)\">${esc(v)}</b>`).join('')}${p.ruolo!=='pr'?` · ${f.length} collegati`:''}</p>\n  ${p.note?`<p class=\"sub\" style=\"color:var(--ink)\">${esc(p.note)}</p>`:''}</div><button data-ed=\"${p.id}\">Modifica anagrafica</button></div>\n  ${scopeTabs()}\n  <div class=\"kpis\"><div class=\"kpi\"><b>${conRis}<small style=\"font-size:14px;color:var(--mute)\"> / ${ser.length}</small></b><span>serate con risultati${capo?' (ramo)':''}</span></div>\n  <div class=\"kpi\"><b>${ser.filter(s=>segno(s).has(id)).length}</b><span>volte a segno (risultati personali)</span></div>\n  <div class=\"kpi\"><b>${tot.b}</b><span>biglietti${capo?' del ramo':''}</span></div><div class=\"kpi\"><b>${tot.t}</b><span>tavoli${capo?' del ramo':''}</span></div>\n  ${capo?`<div class=\"kpi\"><b>${segs[0].tot.b} · ${segs[0].tot.t}</b><span>personali (bigl. · tav.)</span></div>`:''}\n  <div class=\"kpi\"><b>${conRis?m1((tot.b+tot.t)/conRis):'0'}</b><span>persone medie nelle serate attive (TicketSMS + tavoli)</span></div>\n  <div class=\"kpi\"><b>${best&&best.v?best.v:0}</b><span>miglior serata${best&&best.v?' · '+fmtD(best.s.data):''}</span></div>\n  ${inc?`<div class=\"kpi\" style=\"border-top-color:var(--or)\"><b>${eur(tot.e)}</b><span>incasso tavoli${capo?' del ramo':''}${capo&&segs[0].tot.e?' · personale '+eur(segs[0].tot.e):''}</span></div>`:''}</div>\n  ${legend}\n  <div class=\"grid2\"><div class=\"card\"><h3>Biglietti per serata${capo?' · totale e parziali':''}</h3>${chart('qb','b')}</div><div class=\"card\"><h3>Tavoli per serata${capo?' · totale e parziali':''}</h3>${chart('qt','t')}</div>${inc?`<div class=\"card\"><h3>Incasso tavoli per serata (€)${capo?' · totale e parziali':''}</h3>${chart('qe','e')}</div>`:''}</div>\n  ${capo?`<div class=\"card\"><h3>${p.ruolo==='staff'?'Gruppi e PR collegati':'PR collegati'}</h3><div class=\"tbl s\"><table><thead><tr><th></th><th>Nome</th><th>Ruolo</th><th class=\"n\">Serate attive</th><th class=\"n\">Biglietti</th><th class=\"n\">Tavoli</th><th class=\"n\">% persone ramo</th>${inc?'<th class=\"n\">Incasso tavoli</th>':''}</tr></thead><tbody>\n  ${segs.map(sg=>`<tr><td style=\"width:18px\"><i style=\"width:10px;height:10px;border-radius:3px;background:${sg.c};display:inline-block\"></i></td><td>${sg.id?`<button class=\"link\" data-pg=\"${sg.id}\">${esc(sg.n)}</button>`:`<b>${esc(sg.n)}</b>`}</td><td>${sg.id?`<span class=\"tag ${sg.ruolo}\">${RUOLI[sg.ruolo]}</span>`:''}</td><td class=\"n\">${sg.ser}</td><td class=\"n\"><b>${sg.tot.b}</b></td><td class=\"n\">${sg.tot.t}</td><td class=\"n\">${tot.b+tot.t?Math.round((sg.tot.b+sg.tot.t)/(tot.b+tot.t)*100)+'%':'—'}</td>${inc?`<td class=\"n\">${sg.tot.e?eur(sg.tot.e):''}</td>`:''}</tr>`).join('')}</tbody></table></div></div>`:''}`}\n\n/* ---------- classifica a punti ---------- */\nasync function caricaPunti(){const f=S.ptF||'';S.puntiLoad=f;\n  try{const d=await api('GET','/api/punti'+(f?'?f='+encodeURIComponent(f):''));if(S.puntiLoad!==f)return;S.puntiD=d}catch(e){S.puntiD={err:e.message,filtro:f}}\n  if(view()==='punti')render()}\nfunction vPunti(){const ad=S.me.ruolo==='admin',k=S.ptT||'pr',imp=S.imp||{punti_persone:20,punti_euro:500,punti_segno:10,stagione_inizio:''};\n  if(!S.puntiD||S.puntiD.filtro!==(S.ptF||'')){if(S.puntiLoad!==(S.ptF||'')||!S.puntiD)caricaPunti();}\n  const d=S.puntiD&&S.puntiD.filtro===(S.ptF||'')?S.puntiD:null;\n  const loc=S.loc.filter(l=>l.tipo!=='format').sort((a,b)=>a.nome.localeCompare(b.nome,'it')),fm=S.loc.filter(l=>l.tipo==='format').sort((a,b)=>a.nome.localeCompare(b.nome,'it'));\n  const tab=(v,l)=>`<button data-pt=\"${v}\" class=\"${k===v?'on':''}\">${l}</button>`;\n  let corpo='<p class=\"empty\">Calcolo della classifica…</p>';\n  if(d&&d.err)corpo=`<p class=\"empty\">Impossibile caricare la classifica: ${esc(d.err)}</p>`;\n  else if(d){const r=d.righe.filter(x=>x.ruolo===k).sort((a,b)=>b.punti-a.punti||a.nome.localeCompare(b.nome,'it'));\n    let pos=0,prev=null;r.forEach((x,i)=>{if(x.punti!==prev){pos=i+1;prev=x.punti}x.pos=pos});\n    const riga=x=>`<tr ${x.mio?'style=\"background:var(--panel)\"':''}><td class=\"n\" style=\"width:3.5em\">${x.pos<=3&&x.punti?`<span class=\"tag\" style=\"background:${['var(--yel)','#d9d4d0','#e8a36b'][x.pos-1]};color:#2a1309\">${x.pos}°</span>`:x.pos}</td><td>${x.id?`<button class=\"link\" data-pg=\"${x.id}\">${esc(x.nome)}</button>`:`<b>${esc(x.nome)}</b>`}${x.mio?' <span class=\"tag capo\">tuo ramo</span>':''}</td><td class=\"n\" style=\"font-size:16px;width:4.5em\"><b>${x.punti}</b></td></tr>`;\n    const tabella=l=>`<div class=\"tbl\" style=\"max-height:none\"><table><thead><tr><th class=\"n\">#</th><th>Nome</th><th class=\"n\">Punti</th></tr></thead><tbody>${l.map(riga).join('')}</tbody></table></div>`;\n    const meta=Math.ceil(r.length/2);\n    corpo=r.length?`<div class=\"grid2\" style=\"grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));align-items:start\">${tabella(r.slice(0,meta))}${r.length>1?tabella(r.slice(meta)):''}</div>`:'<p class=\"empty\">Nessuno ha ancora risultati in questa stagione.</p>'}\n  return `<div class=\"top\"><div class=\"sp\"><h2>Classifica a punti</h2><p class=\"sub\">1 punto ogni <b>${imp.punti_persone}</b> persone (TicketSMS + tavoli) e ogni <b>${eur(imp.punti_euro*100)}</b> di incasso tavoli, sui totali della stagione iniziata il <b>${fmtD(imp.stagione_inizio)}</b>, più <b>${imp.punti_segno}</b> punti per ogni serata in cui si va a segno (più del proprio miglior risultato nelle 2 serate precedenti dello stesso format). Capi PR e Capi staff sommano anche i risultati del proprio gruppo.</p></div></div>\n  ${ad?`<div class=\"card\" style=\"margin-bottom:12px\"><h3>Impostazioni dei punti</h3><div class=\"row\"><label>Inizio stagione<input id=\"iS\" type=\"date\" value=\"${esc(imp.stagione_inizio)}\"></label><label>Persone per 1 punto<input id=\"iP\" type=\"number\" min=\"1\" value=\"${imp.punti_persone}\" style=\"width:130px\"></label><label>Euro di incasso per 1 punto<input id=\"iE\" type=\"number\" min=\"1\" value=\"${imp.punti_euro}\" style=\"width:150px\"></label><label>Punti bonus per serata a segno<input id=\"iB\" type=\"number\" min=\"0\" value=\"${imp.punti_segno}\" style=\"width:150px\"></label><button class=\"pri\" id=\"iA\" style=\"align-self:flex-end\">Salva</button></div><p class=\"msg\" id=\"iM\"></p></div>`:''}\n  <div class=\"row\" style=\"margin-bottom:10px\"><div class=\"tabs\" style=\"margin:0\">${tab('pr','PR')}${tab('capo','Capi PR')}${tab('staff','Capi staff')}</div><span class=\"sp\"></span>\n  <label style=\"display:flex;gap:6px;align-items:center\">Serate <select id=\"ptF\" style=\"width:auto\"><option value=\"\">Tutte</option>${loc.length?`<optgroup label=\"Locali\">${loc.map(l=>`<option value=\"${l.id}\" ${S.ptF===l.id?'selected':''}>${esc(l.nome)}</option>`).join('')}</optgroup>`:''}${fm.length?`<optgroup label=\"Format\">${fm.map(l=>`<option value=\"${l.id}\" ${S.ptF===l.id?'selected':''}>${esc(l.nome)}</option>`).join('')}</optgroup>`:''}</select></label></div>\n  ${corpo}`}\n\n/* ---------- accessi ---------- */\nfunction vAccessi(){const st=S.pr.filter(p=>p.ruolo==='staff').sort(sortNome);\n  return `<div class=\"top\"><div class=\"sp\"><h2>Accessi</h2><p class=\"sub\">Chi può entrare nel sito. Ogni capo staff vede e modifica solo il proprio ramo; gli amministratori si impostano nella variabile ADMIN_EMAILS del Worker.</p></div></div>\n  <div class=\"card\" style=\"margin-bottom:12px\"><h3>Aggiungi un capo staff</h3><div class=\"row\"><input id=\"aE\" type=\"email\" placeholder=\"email@esempio.it\" style=\"flex:2 1 220px;width:auto\">\n  <select id=\"aP\" style=\"flex:1 1 180px;width:auto\">${st.length?st.map(p=>`<option value=\"${p.id}\">${esc(nome(p))}</option>`).join(''):'<option value=\"\">Crea prima un Capo staff in Archivio</option>'}</select><button class=\"pri\" id=\"aA\">Abilita</button></div><p class=\"msg\" id=\"aM\"></p></div>\n  <div class=\"tbl\"><table class=\"stack\"><thead><tr><th>Email</th><th>Capo staff</th><th></th></tr></thead><tbody>\n  ${S.utenti.length?S.utenti.map(u=>`<tr><td>${esc(u.email)}</td><td>${u.persona_id&&byId(u.persona_id)?`<button class=\"link\" data-pg=\"${u.persona_id}\">${esc(nome(byId(u.persona_id)))}</button>`:'<span class=\"note\">Persona eliminata</span>'}</td><td class=\"n\"><button class=\"danger\" data-du=\"${esc(u.email)}\">Togli accesso</button></td></tr>`).join(''):'<tr><td colspan=\"3\"><p class=\"empty\">Nessun capo staff abilitato.</p></td></tr>'}</tbody></table></div>`}\n\n/* ---------- render ---------- */\nfunction render(){const v=view();for(const a of document.querySelectorAll('#nav a'))a.classList.toggle('on',a.dataset.v===v);\n  if(!S.me){if(!S.got.pr)return;$('#main').innerHTML='<p class=\"empty\">Dati non disponibili.</p>';return}\n  const ad=S.me.ruolo==='admin';for(const a of document.querySelectorAll('#nav a[data-adm]'))a.hidden=!ad;\n  $('#who').innerHTML=`${esc(S.me.email)}${ad?' · amministratore':' · capo staff'} · <a href=\"/cdn-cgi/access/logout\">Esci</a>`;\n  if(!ad&&(v==='serate'||v==='accessi')){location.hash='archivio';return}\n  const fo=document.activeElement,fid=fo&&fo.id&&$('#main').contains(fo)?fo.id:null,sel=fid&&fo.selectionStart!=null?[fo.selectionStart,fo.selectionEnd]:null;\n  S.charts={};$('#main').innerHTML=({archivio:vArchivio,struttura:vStruttura,serate:vSerate,report:vReport,persona:vPersona,punti:vPunti,accessi:vAccessi})[v]();draw();if(v==='archivio')upd();\n  if(fid){const e=document.getElementById(fid);if(e){e.focus();if(sel&&e.setSelectionRange)try{e.setSelectionRange(...sel)}catch(_){}}}}\n\n/* ---------- scheda persona ---------- */\nfunction openPR(id){const p=id?byId(id):{ruolo:'pr'};if(!p)return;S.draft={k:'pr',id};\n  const ad=S.me&&S.me.ruolo==='admin',self=!ad&&id&&id===S.me.persona_id,RO=RUOLI;\n  const dl=(f)=>`<datalist id=\"d-${f}\">${opts(f).map(v=>`<option value=\"${esc(v)}\">`).join('')}</datalist>`;\n  const f=(k,lab,type='text',w='')=>`<label class=\"${w}\">${lab}<input id=\"p-${k}\" type=\"${type}\" value=\"${esc(p[k]??'')}\" ${k==='scuola'||k==='zona'?`list=\"d-${k}\"`:''} ${type==='number'?'inputmode=\"numeric\" min=\"1990\" max=\"2020\"':''}></label>`;\n  $('#sheet').innerHTML=`<div class=\"row\"><h2 class=\"sp\">${id?esc(nome(p)):'Nuova persona'}</h2><button class=\"ghost\" data-x=\"1\">Chiudi</button></div>\n  <div class=\"form\">${f('nome','Nome')}${f('cognome','Cognome')}\n  <label>Ruolo<select id=\"p-ruolo\" ${self?'disabled':''}>${Object.entries(self?RUOLI:RO).map(([k,v])=>`<option value=\"${k}\" ${k===p.ruolo?'selected':''}>${v}</option>`).join('')}</select></label>\n  <label>Superiore<select id=\"p-parent\"></select></label>\n  ${f('anno','Anno di nascita','number')}${f('tel','Telefono','tel')}${f('scuola','Scuola')}${f('zona','Zona')}\n  <label class=\"w\">Note<textarea id=\"p-note\">${esc(p.note||'')}</textarea></label></div>${dl('scuola')}${dl('zona')}\n  ${id?`<p class=\"note\">Totale: ${BT(vend(id,S.ser))} in ${S.ser.filter(s=>(s.ris||{})[id]).length} serate</p>`:''}\n  <p class=\"msg\" id=\"pM\"></p><div class=\"row\"><button class=\"pri\" id=\"pS\">Salva</button>${id&&!self?'<span class=\"sp\"></span><button class=\"danger\" id=\"pD\">Elimina</button>':''}</div>`;\n  const fill=()=>{const r=$('#p-ruolo').value,cur=$('#p-parent').dataset.v??p.parent??'';\n    const disc=new Set();if(id){const q=[id];while(q.length){const c=q.pop();for(const k of figli(c))if(!disc.has(k.id)){disc.add(k.id);q.push(k.id)}}}\n    const ok=S.pr.filter(x=>x.id!==id&&!disc.has(x.id)&&(r==='capo'||r==='staff'?x.ruolo==='staff':x.ruolo!=='pr')).sort((a,b)=>ORD[a.ruolo]-ORD[b.ruolo]||sortNome(a,b));\n    $('#p-parent').innerHTML=(ad||self?`<option value=\"\">${r==='staff'?'Nessuno (al vertice)':'Nessuno (singolo)'}</option>`:'')+ok.map(x=>`<option value=\"${x.id}\" ${x.id===cur?'selected':''}>${esc(nome(x))} · ${RUOLI[x.ruolo]}</option>`).join('');\n    $('#p-parent').disabled=!!self};\n  fill();$('#p-ruolo').onchange=fill;$('#p-parent').onchange=e=>e.target.dataset.v=e.target.value;\n  $('#pS').onclick=()=>salvaPR(id);if(id&&!self)$('#pD').onclick=e=>eliminaPR(id,e.target);\n  $('#modal').classList.add('on');$('#p-nome').focus()}\nasync function salvaPR(id){const g=k=>$('#p-'+k).value.trim(),m=$('#pM');\n  const d={nome:g('nome'),cognome:g('cognome'),ruolo:$('#p-ruolo').value,parent:$('#p-parent').value||null,anno:g('anno')?parseInt(g('anno'),10):null,tel:g('tel'),scuola:g('scuola'),zona:g('zona'),note:$('#p-note').value.trim()};\n  if(!d.nome&&!d.cognome){m.textContent='Serve almeno il nome o il cognome.';return}\n  if(d.anno!=null&&(isNaN(d.anno)||d.anno<1950||d.anno>2025)){m.textContent='Anno di nascita non valido.';return}\n  if(id){const f=figli(id);if(d.ruolo==='pr'&&f.length){m.textContent=`Ha ${f.length} persone collegate: spostale prima di farlo diventare PR.`;return}\n    if(d.ruolo==='capo'&&f.some(x=>x.ruolo!=='pr')){m.textContent='Ha Capi staff o Capi PR sotto di sé: spostali prima di farlo diventare Capo PR.';return}}\n  if(!S.db){m.textContent='Archivio non raggiungibile: impossibile salvare.';return}\n  $('#pS').disabled=true;try{const c=S.db.collection('pr');await (id?c.doc(id):c.doc()).set(d);chiudi();toast('Salvato')}catch(e){m.textContent='Errore nel salvataggio: '+(e.message||e.code);$('#pS').disabled=false}}\nasync function eliminaPR(id,b){const f=figli(id),par=byId(id)?.parent;\n  if(!b.dataset.c){b.dataset.c=1;b.textContent='Conferma eliminazione';$('#pM').textContent=(f.length?`Le ${f.length} persone collegate passeranno ${par?'sotto '+nome(byId(par)):'senza superiore'}. `:'')+'I risultati già inseriti restano nelle serate.';return}\n  b.disabled=true;try{await S.db.collection('pr').doc(id).delete();chiudi();toast('Eliminato');if(location.hash==='#persona-'+id)location.hash='archivio'}catch(e){$('#pM').textContent='Errore: '+(e.message||e.code);b.disabled=false}}\n\n/* ---------- scheda serata ---------- */\nfunction openSerata(id){const s=id?S.ser.find(x=>x.id===id):{data:new Date().toISOString().slice(0,10),ris:{}};if(!s)return;\n  S.draft={k:'ser',id,ris:{...(s.ris||{})}};S.rq='';\n  const os=(t,sel)=>`<option value=\"\">Nessuno</option>`+S.loc.filter(l=>(l.tipo==='format')===(t==='format')).sort((a,b)=>a.nome.localeCompare(b.nome,'it')).map(l=>`<option value=\"${l.id}\" ${l.id===sel?'selected':''}>${esc(l.nome)}${l.tipo==='format'&&l.eta_min?' · '+l.eta_min+'+':''}</option>`).join('')+`<option value=\"__new\">+ Nuovo ${t}…</option>`;\n  S.osel=os;\n  $('#sheet').innerHTML=`<div class=\"row\"><h2 class=\"sp\">${id?esc(s.nome||'Serata'):'Nuova serata'}</h2><button class=\"ghost\" data-x=\"1\">Chiudi</button></div>\n  <div class=\"form\"><label>Data<input id=\"s-data\" type=\"date\" value=\"${esc(s.data||'')}\"></label><label>Nome serata<input id=\"s-nome\" value=\"${esc(s.nome||'')}\" placeholder=\"Es. VidaLoca\"></label>\n  <label>Locale<select id=\"s-loc\">${os('locale',s.loc)}</select></label><label>Format<select id=\"s-fmt\">${os('format',s.fmt)}</select></label>\n  <div class=\"w row\" id=\"s-new\" hidden><input id=\"s-newN\" style=\"flex:2 1 200px;width:auto\"><input id=\"s-newE\" type=\"number\" inputmode=\"numeric\" min=\"6\" max=\"99\" placeholder=\"Età minima\" style=\"flex:1 1 120px;width:auto\" hidden><select id=\"s-newM\" style=\"flex:1 1 140px;width:auto\" hidden><option value=\"persone\">A persone</option><option value=\"incasso\">A incasso</option></select><button class=\"pri\" id=\"s-newA\">Crea</button><button class=\"ghost\" id=\"s-newX\">Annulla</button></div></div>\n  <div class=\"row\"><h3 class=\"sp\" style=\"margin:0\">Risultati PR</h3><span class=\"tot\"><b id=\"sT\">0</b> bigl. · <b id=\"sV\">0</b> tav.<span id=\"sEw\"> · <b id=\"sE\">€ 0</b></span> · <b id=\"sN\">0</b> PR con risultati</span></div>\n  <input id=\"s-q\" type=\"search\" placeholder=\"Cerca un PR…\" style=\"margin-top:8px\"><div class=\"rl\" id=\"rl\"></div>\n  <details><summary style=\"cursor:pointer;min-height:44px;display:flex;align-items:center\">Incolla una lista (una riga per PR: Nome Cognome biglietti tavoli · nei format a incasso: Nome Cognome importo)</summary>\n  <textarea id=\"s-paste\" placeholder=\"Mario Rossi 12 1&#10;Giulia Bianchi;7\"></textarea><div class=\"row\" style=\"margin-top:8px\"><button id=\"s-ap\">Applica lista</button></div></details>\n  <p class=\"msg\" id=\"sM\"></p><div class=\"row\"><button class=\"pri\" id=\"sS\">Salva serata</button>${id?'<span class=\"sp\"></span><button class=\"danger\" id=\"sD\">Elimina serata</button>':''}</div>`;\n  listaRis();\n  let nuovoTipo=null,prec={locale:s.loc||'',format:s.fmt||''};\n  const selDi=t=>$(t==='format'?'#s-fmt':'#s-loc');\n  for(const t of ['locale','format'])selDi(t).onchange=e=>{if(e.target.value==='__new'){nuovoTipo=t;$('#s-new').hidden=false;$('#s-newN').placeholder='Nome del nuovo '+t;$('#s-newN').value='';$('#s-newE').hidden=$('#s-newM').hidden=t!=='format';$('#s-newE').value='';$('#s-newN').focus()}else{prec[t]=e.target.value;if(t==='format')listaRis()}};\n  const chiudiNuovo=()=>{if(nuovoTipo)selDi(nuovoTipo).value=prec[nuovoTipo];nuovoTipo=null;$('#s-new').hidden=true};\n  $('#s-newX').onclick=chiudiNuovo;\n  $('#s-newE').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#s-newA').click()}};\n  $('#s-newN').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#s-newA').click()}};\n  $('#s-newA').onclick=async()=>{const n=$('#s-newN').value.trim(),t=nuovoTipo,m=$('#sM'),eta=$('#s-newE').value;if(!n){m.textContent='Scrivi il nome del nuovo '+t+'.';return}\n    const esiste=S.loc.find(l=>l.tipo===t&&norm(l.nome)===norm(n));\n    if(!esiste&&t==='format'&&!eta){m.className='msg';m.textContent='Indica l\\'età minima del format.';return}\n    try{if(!esiste)await api('POST','/api/locali',{nome:n,tipo:t,eta_min:eta,misura:$('#s-newM').value});await load();\n      const nl=S.loc.find(l=>l.tipo===t&&norm(l.nome)===norm(n));\n      for(const k of ['locale','format'])selDi(k).innerHTML=S.osel(k,k===t?nl?.id:prec[k]);\n      prec[t]=nl?.id||'';nuovoTipo=null;$('#s-new').hidden=true;if(t==='format')listaRis();m.className='msg ok';m.textContent=esiste?`${n} esisteva già: l'ho selezionato.`:`${t==='format'?'Format':'Locale'} \"${n}\" creato.`}\n    catch(er){m.className='msg';m.textContent='Errore: '+(er.message||er.code)}};\n  $('#s-q').oninput=e=>{S.rq=e.target.value;listaRis()};\n  $('#rl').oninput=e=>{const i=e.target.dataset.r,k=e.target.dataset.k;if(!i)return;const n=k==='e'?cent(e.target.value):Math.max(0,parseInt(e.target.value,10)||0);\n    const o={...R(S.draft,i)};o[k]=n;setRis(i,o);e.target.closest('.rr').classList.toggle('has',!!S.draft.ris[i]);totRis()};\n  $('#s-ap').onclick=applicaLista;$('#sS').onclick=()=>salvaSerata(id);\n  if(id)$('#sD').onclick=async e=>{const b=e.target;if(!b.dataset.c){b.dataset.c=1;b.textContent='Conferma eliminazione';return}\n    b.disabled=true;try{await S.db.collection('serate').doc(id).delete();chiudi();toast('Serata eliminata')}catch(er){$('#sM').textContent='Errore: '+(er.message||er.code);b.disabled=false}};\n  $('#modal').classList.add('on')}\nconst setRis=(i,o)=>{if(o.b>=1||o.t>=1||o.e>0)S.draft.ris[i]={b:o.b||0,t:o.t||0,e:o.e||0};else delete S.draft.ris[i]};\nconst incAttivo=()=>misuraDi($('#s-fmt')?.value)==='incasso'||Object.values(S.draft.ris).some(r=>r&&r.e>0);\nfunction totRis(){const v=sumSer(S.draft);$('#sT').textContent=v.b;$('#sV').textContent=v.t;$('#sE').textContent=eur(v.e);$('#sEw').hidden=!incAttivo();$('#sN').textContent=Object.keys(S.draft.ris).length}\nfunction listaRis(){const q=norm(S.rq),r=S.draft.ris;\n  const inc=incAttivo(),cl=inc?' inc':'';\n  const inp=(id,k,n)=>{const v=R(S.draft,id)[k];return k==='e'?`<input type=\"text\" inputmode=\"decimal\" data-r=\"${id}\" data-k=\"e\" value=\"${v?String(v/100).replace('.',','):''}\" placeholder=\"€ 0\" aria-label=\"Incasso tavoli di ${esc(n)}\">`:`<input type=\"number\" inputmode=\"numeric\" min=\"0\" data-r=\"${id}\" data-k=\"${k}\" value=\"${v||''}\" placeholder=\"0\" aria-label=\"${k==='b'?'Biglietti':'Tavoli'} di ${esc(n)}\">`};\n  const cells=(id,n)=>inp(id,'b',n)+inp(id,'t',n)+(inc?inp(id,'e',n):'');\n  const head=`<div class=\"rr${cl}\" style=\"position:sticky;top:0;background:var(--bg);z-index:1;font-size:13px;color:var(--mute);font-weight:600\"><span>PR</span><span style=\"text-align:right\">Biglietti</span><span style=\"text-align:right\">Tavoli</span>${inc?'<span style=\"text-align:right\">Incasso tav. €</span>':''}</div>`;\n  const l=[...S.pr].filter(p=>!q||norm(nome(p)).includes(q)).sort((a,b)=>(r[b.id]?1:0)-(r[a.id]?1:0)||sortNome(a,b));\n  const orfani=Object.keys(r).filter(k=>!byId(k));\n  $('#rl').innerHTML=(l.length||orfani.length)?head+l.map(p=>`<div class=\"rr${cl} ${r[p.id]?'has':''}\"><span>${esc(nome(p))} <span class=\"note\" style=\"display:inline\">${RUOLI[p.ruolo]}${p.parent?' · '+esc(nome(byId(p.parent))):''}</span></span>${cells(p.id,nome(p))}</div>`).join('')+orfani.map(k=>`<div class=\"rr${cl} has\"><span>PR eliminato</span>${cells(k,'PR eliminato')}</div>`).join('')\n    :'<p class=\"empty\" style=\"padding:0 12px\">Nessun PR in archivio con questo nome.</p>';totRis()}\nfunction applicaLista(){const idx=new Map();for(const p of S.pr){idx.set(norm(`${p.nome||''} ${p.cognome||''}`),p.id);idx.set(norm(`${p.cognome||''} ${p.nome||''}`),p.id)}\n  const inc=misuraDi($('#s-fmt').value)==='incasso';\n  const no=[];let ok=0;for(const riga of $('#s-paste').value.split('\\n')){const t=riga.trim();if(!t)continue;\n    if(inc){const mi=t.match(/^(.*?)[\\s;:\\t]+€?\\s*([\\d.]+(?:,\\d{1,2})?)\\s*€?\\s*$/);const id=mi&&idx.get(norm(mi[1].replace(/[;:\\t]/g,' ')));if(!id){no.push(mi?mi[1]:t);continue}setRis(id,{...R(S.draft,id),e:cent(mi[2])});ok++;continue}\n    const m=t.match(/^(.*?)[\\s;,:\\t]+(\\d+)(?:[\\s;,:\\t]+(\\d+))?\\s*$/);\n    const id=m&&idx.get(norm(m[1].replace(/[;,:\\t]/g,' ')));if(!id){no.push(m?m[1]:t);continue}setRis(id,{b:parseInt(m[2],10),t:m[3]?parseInt(m[3],10):R(S.draft,id).t});ok++}\n  listaRis();const msg=$('#sM');msg.className='msg'+(no.length?'':' ok');msg.textContent=`${ok} righe applicate.`+(no.length?` Non trovati in archivio: ${no.slice(0,8).join(', ')}${no.length>8?'…':''}`:'')}\nasync function salvaSerata(id){const m=$('#sM');m.className='msg';const d={data:$('#s-data').value,nome:$('#s-nome').value.trim(),loc:($('#s-loc').value==='__new'?'':$('#s-loc').value)||null,fmt:($('#s-fmt').value==='__new'?'':$('#s-fmt').value)||null,ris:{}};\n  if(!d.data){m.textContent='Inserisci la data della serata.';return}\n  for(const k of Object.keys(S.draft.ris)){const r=R(S.draft,k);if(r.b>=1||r.t>=1||r.e>0)d.ris[k]={b:r.b,t:r.t,e:r.e}}\n  if(!S.db){m.textContent='Archivio non raggiungibile: impossibile salvare.';return}\n  $('#sS').disabled=true;try{const c=S.db.collection('serate');await (id?c.doc(id):c.doc()).set(d);chiudi();toast('Serata salvata')}catch(e){m.textContent='Errore nel salvataggio: '+(e.message||e.code);$('#sS').disabled=false}}\nfunction openLoc(id){const l=S.loc.find(x=>x.id===id);if(!l)return;S.draft={k:'loc',id};\n  $('#sheet').innerHTML=`<div class=\"row\"><h2 class=\"sp\">${l.tipo==='format'?'Format':'Locale'}</h2><button class=\"ghost\" data-x=\"1\">Chiudi</button></div>\n  <div class=\"form\"><label>Nome<input id=\"e-nome\" value=\"${esc(l.nome)}\"></label>${l.tipo==='format'?`<label>Età minima del target<input id=\"e-eta\" type=\"number\" inputmode=\"numeric\" min=\"6\" max=\"99\" value=\"${esc(l.eta_min||'')}\" placeholder=\"es. 14\"></label><label>Misura principale<select id=\"e-mis\"><option value=\"persone\" ${l.misura!=='incasso'?'selected':''}>Persone (TicketSMS + tavoli)</option><option value=\"incasso\" ${l.misura==='incasso'?'selected':''}>Incasso tavoli (€)</option></select></label>`:''}</div>\n  <p class=\"msg\" id=\"eM\"></p><div class=\"row\"><button class=\"pri\" id=\"eS\">Salva</button></div>`;\n  $('#eS').onclick=async()=>{const b={nome:$('#e-nome').value.trim(),eta_min:l.tipo==='format'?$('#e-eta').value:null,misura:l.tipo==='format'?$('#e-mis').value:null};\n    try{await api('PUT','/api/locali/'+id,b);chiudi();toast('Salvato');await load()}catch(er){$('#eM').textContent=er.message}};\n  $('#modal').classList.add('on');$('#e-nome').focus()}\nfunction chiudi(){$('#modal').classList.remove('on');S.draft=null}\n\n/* ---------- eventi ---------- */\ndocument.addEventListener('click',async e=>{const th=e.target.closest('th[data-so]');if(th){const k=th.dataset.so;S.so=S.so.k===k?{k,d:-S.so.d}:{k,d:k==='b'||k==='t'?-1:1};render();return}\n  const t=e.target.closest('button,[data-rp]');if(!t)return;const d=t.dataset;\n  if(d.pg){location.hash='persona-'+d.pg;scrollTo(0,0)}else if(d.back){if(history.length>1)history.back();else location.hash='archivio'}else if(d.ed)openPR(d.ed);else if(d.new)openPR(null);else if(d.ns)openSerata(null);else if(d.es)openSerata(d.es);else if(d.x)chiudi();\n  else if(d.rp){S.rep=d.rp;S.repPr='';render()}else if(d.cl){S.clT=d.cl;render()}else if(d.pt){S.ptT=d.pt;render()}else if(d.tp){S.repPr=d.tp;render();$('#rpP')?.scrollIntoView({block:'center'})}\n  else if(t.id==='clr'){S.q=S.fR=S.fS=S.fZ='';render()}\n  else if(t.id==='iA'){t.disabled=true;try{await api('PUT','/api/impostazioni',{stagione_inizio:$('#iS').value,punti_persone:$('#iP').value,punti_euro:$('#iE').value,punti_segno:$('#iB').value});toast('Impostazioni salvate');await load()}catch(er){$('#iM').textContent=er.message;t.disabled=false}}\n  else if(t.id==='aA'){const em=$('#aE').value.trim(),pid=$('#aP').value;if(!em||!pid){$('#aM').textContent='Scrivi l\\'email e scegli il capo staff.';return}\n    t.disabled=true;try{await api('POST','/api/utenti',{email:em,persona_id:pid});toast('Accesso abilitato');await load()}catch(er){$('#aM').textContent=er.message;t.disabled=false}}\n  else if(d.du){if(!t.dataset.c){t.dataset.c=1;t.textContent='Conferma';return}try{await api('DELETE','/api/utenti/'+encodeURIComponent(d.du));toast('Accesso tolto');await load()}catch(er){toast(er.message)}}\n  else if(d.el)openLoc(d.el);\n  else if(t.id==='lA'){const n=$('#lN').value.trim(),ty=$('#lT').value,eta=$('#lE').value;if(!n){$('#lM').textContent='Scrivi il nome.';return}\n    if(ty==='format'&&!eta){$('#lM').textContent='Indica l\\'età minima del format.';return}\n    if(S.loc.some(l=>norm(l.nome)===norm(n)&&l.tipo===ty)){$('#lM').textContent='Esiste già.';return}\n    try{await api('POST','/api/locali',{nome:n,tipo:ty,eta_min:eta,misura:$('#lMis').value});toast('Aggiunto');await load()}catch(er){$('#lM').textContent='Errore: '+(er.message||er.code)}}\n  else if(d.dl){const u=S.ser.filter(s=>s.loc===d.dl||s.fmt===d.dl).length;if(u){$('#lM').textContent=`Usato in ${u} serate: non si può eliminare.`;return}\n    if(!t.dataset.c){t.dataset.c=1;t.textContent='Elimina?';return}try{await S.db.collection('locali').doc(d.dl).delete();toast('Eliminato')}catch(er){$('#lM').textContent='Errore: '+(er.message||er.code)}}});\n$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')chiudi()});\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal').classList.contains('on'))chiudi()});\nconst upd=()=>{$('#tb').innerHTML=righe();const c=$('#cnt');if(c)c.textContent=`${filtrati().length} di ${S.pr.length} persone`};\ndocument.addEventListener('input',e=>{const id=e.target.id;if(id==='q'){S.q=e.target.value;upd()}});\ndocument.addEventListener('change',e=>{const id=e.target.id;if(['fR','fS','fZ'].includes(id)){S[id]=e.target.value;upd()}else if(id==='rpP'){S.repPr=e.target.value;render()}else if(id==='lT'){$('#lE').hidden=$('#lMis').hidden=e.target.value!=='format'}else if(id==='ptF'){S.ptF=e.target.value;S.puntiD=null;render()}else if(id==='clS'){S.clS=e.target.value;render()}else if(id==='clF'){S.rep=e.target.value;S.repPr='';render()}});\nwindow.addEventListener('hashchange',render);\n\n/* ---------- dati (API del sito) ---------- */\nconst VER='7e0dc85b81f1';\nconst MAP={pr:'persone',locali:'locali',serate:'serate'};\nasync function api(m,u,b){const r=await fetch(u,{method:m,headers:{'content-type':'application/json','x-ver':VER},body:b?JSON.stringify(b):undefined,credentials:'same-origin'});\n  let j={};try{j=await r.json()}catch(_){}\n  if(r.status===401||r.redirected&&!r.url.includes('/api/')){location.reload();throw {message:'Sessione scaduta'}}\n  if(j.reload){toast(j.error);setTimeout(()=>location.reload(),1500)}\n  if(!r.ok)throw {message:j.error||('Errore '+r.status)};return j}\nasync function load(){try{const d=await api('GET','/api/data');if(d.ver&&d.ver!==VER&&!S.me){location.reload();return}S.me=d.me;S.pr=d.persone;S.loc=d.locali;S.ser=d.serate;S.utenti=d.utenti||[];S.imp=d.imp||S.imp;S.puntiD=null;S.got={pr:1,loc:1,ser:1};S.segno=calcSegno();banner(d.ver&&d.ver!==VER?'È disponibile una versione nuova del sito: ricarica la pagina.':'');\n  render();if(S.draft&&S.draft.k==='ser')listaRis()}catch(e){banner('Impossibile caricare i dati: '+(e.message||e));S.got={pr:1,loc:1,ser:1};render()}}\nS.db={collection:c=>({doc:id=>({set:async d=>{await api(id?'PUT':'POST',`/api/${MAP[c]}${id?'/'+id:''}`,d);await load()},\n  delete:async()=>{await api('DELETE',`/api/${MAP[c]}/${id}`);await load()}})})};\nwindow.addEventListener('focus',()=>{if(!$('#modal').classList.contains('on'))load()});\nload();\nrender();\n}\n</script>\n</body>\n</html>\n";
const VER = "7e0dc85b81f1"; // versione della pagina: se il browser ha una pagina vecchia, la ricarica prima di salvare

const RUOLI = ['staff', 'capo', 'pr'];
const json = (d, s = 200) => new Response(JSON.stringify(d), { status: s, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' } });
const err = (m, s = 400) => json({ error: m }, s);
const SEC = { 'x-frame-options': 'DENY', 'referrer-policy': 'no-referrer', 'x-content-type-options': 'nosniff' };
const page = (body, s = 200) => new Response(body, { status: s, headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store', ...SEC } });
const msgPage = (t, m) => page(`<!DOCTYPE html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rete PR</title><body style="font:16px system-ui;max-width:520px;margin:15vh auto;padding:0 20px;color:#2a1309"><h1 style="color:#e3301c">${t}</h1><p>${m}</p><p><a href="/cdn-cgi/access/logout">Esci e accedi con un'altra email</a></p></body></html>`, 403);

/* ---------- verifica del token di Cloudflare Access ---------- */
let JWKS = null, JWKS_T = 0;
const b64u = s => Uint8Array.from(atob(s.replace(/-/g, '+').replace(/_/g, '/').padEnd(Math.ceil(s.length / 4) * 4, '=')), c => c.charCodeAt(0));
async function chiavi(env) {
  if (JWKS && Date.now() - JWKS_T < 3600e3) return JWKS;
  const r = await fetch(`https://${env.TEAM_DOMAIN}/cdn-cgi/access/certs`);
  JWKS = (await r.json()).keys || []; JWKS_T = Date.now(); return JWKS;
}
async function verifica(token, env) {
  const [h, p, s] = (token || '').split('.'); if (!s) return null;
  try {
    const head = JSON.parse(new TextDecoder().decode(b64u(h)));
    const pay = JSON.parse(new TextDecoder().decode(b64u(p)));
    const k = (await chiavi(env)).find(x => x.kid === head.kid); if (!k) return null;
    const key = await crypto.subtle.importKey('jwk', { kty: k.kty, n: k.n, e: k.e, alg: 'RS256', ext: true }, { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['verify']);
    if (!await crypto.subtle.verify('RSASSA-PKCS1-v1_5', key, b64u(s), new TextEncoder().encode(h + '.' + p))) return null;
    const aud = Array.isArray(pay.aud) ? pay.aud : [pay.aud];
    if (!aud.includes(env.POLICY_AUD)) return null;
    if (!pay.exp || pay.exp * 1000 < Date.now()) return null;
    if (pay.iss !== `https://${env.TEAM_DOMAIN}`) return null;
    return (pay.email || '').toLowerCase() || null;
  } catch { return null; }
}
async function chiSei(req, env) {
  const url = new URL(req.url);
  // Solo per i test in locale (wrangler dev su localhost): mai attivo sul sito pubblicato.
  if (env.DEV_EMAIL && ['localhost', '127.0.0.1'].includes(url.hostname)) return (req.headers.get('x-dev-email') || env.DEV_EMAIL).toLowerCase();
  if (!env.TEAM_DOMAIN || !env.POLICY_AUD) return { config: true };
  return verifica(req.headers.get('Cf-Access-Jwt-Assertion'), env);
}

/* ---------- utilità sui dati ---------- */
const euroCent = v => { const n = parseFloat(String(v ?? '').replace(/\./g, '').replace(',', '.')); return Number.isFinite(n) && n > 0 ? Math.round(n * 100) : 0; };
const misura = v => v === 'incasso' ? 'incasso' : 'persone';
const etaMin = v => { const n = parseInt(v, 10); return Number.isFinite(n) && n >= 6 && n <= 99 ? n : null; };
const uid = () => crypto.randomUUID().replace(/-/g, '').slice(0, 20);
const txt = (v, n = 200) => (v == null ? '' : String(v)).trim().slice(0, n);
async function tutte(env) { return (await env.DB.prepare('SELECT * FROM persone').all()).results; }
function ramo(persone, rootId) {
  const ids = new Set([rootId]); let cambiato = true;
  while (cambiato) { cambiato = false; for (const p of persone) if (p.parent && ids.has(p.parent) && !ids.has(p.id)) { ids.add(p.id); cambiato = true; } }
  return ids;
}
function pulisci(b) {
  const anno = b.anno === '' || b.anno == null ? null : parseInt(b.anno, 10);
  return {
    nome: txt(b.nome, 80), cognome: txt(b.cognome, 80), anno: Number.isFinite(anno) ? anno : null,
    scuola: txt(b.scuola, 120), zona: txt(b.zona, 120), tel: txt(b.tel, 40), note: txt(b.note, 1000),
    ruolo: RUOLI.includes(b.ruolo) ? b.ruolo : 'pr', parent: b.parent ? txt(b.parent, 40) : null,
  };
}
// Regole dell'albero, uguali per tutti
function controllaAlbero(d, id, persone) {
  if (!d.nome && !d.cognome) return 'Serve almeno il nome o il cognome.';
  if (d.anno != null && (d.anno < 1950 || d.anno > 2025)) return 'Anno di nascita non valido.';
  if (d.parent) {
    if (d.parent === id) return 'Una persona non può essere superiore di sé stessa.';
    const par = persone.find(p => p.id === d.parent); if (!par) return 'Superiore non trovato.';
    if (id && ramo(persone, id).has(d.parent)) return 'Non puoi mettere una persona sotto qualcuno del suo stesso ramo.';
    if (d.ruolo === 'staff' && par.ruolo !== 'staff') return 'Un Capo staff può stare solo sotto un altro Capo staff.';
    if (d.ruolo === 'capo' && par.ruolo !== 'staff') return 'Un Capo PR può stare solo sotto un Capo staff.';
    if (d.ruolo === 'pr' && par.ruolo === 'pr') return 'Un PR può stare solo sotto un Capo staff o un Capo PR.';
  }
  if (id) {
    const figli = persone.filter(p => p.parent === id);
    if (d.ruolo === 'pr' && figli.length) return `Ha ${figli.length} persone collegate: spostale prima di farlo diventare PR.`;
    if (d.ruolo === 'capo' && figli.some(f => f.ruolo !== 'pr')) return 'Ha Capi staff o Capi PR sotto di sé: spostali prima.';
  }
  return null;
}

/* ---------- classifica a punti ---------- */
async function impostazioni(env) {
  const rows = (await env.DB.prepare('SELECT * FROM impostazioni').all()).results;
  const o = Object.fromEntries(rows.map(r => [r.chiave, r.valore]));
  return { stagione_inizio: o.stagione_inizio || '2000-01-01', punti_persone: parseInt(o.punti_persone, 10) || 20, punti_euro: parseInt(o.punti_euro, 10) || 500, punti_segno: o.punti_segno != null ? parseInt(o.punti_segno, 10) || 0 : 10 };
}
// Punti interi sui totali della stagione: PR = personali; Capi PR e Capi staff = personali + tutto il gruppo.
// La classifica mostra solo nome e punti (nessun numero di persone, incasso o superiore).
async function classificaPunti(env, me, admin, filtro) {
  const imp = await impostazioni(env);
  const persone = await tutte(env);
  const [serR, locR, risR] = await Promise.all([
    env.DB.prepare('SELECT id, data, loc, fmt FROM serate ORDER BY data, id').all(),
    env.DB.prepare('SELECT id, misura FROM locali').all(),
    env.DB.prepare('SELECT serata_id, persona_id, b, t, e FROM risultati').all()]);
  const incasso = new Set(locR.results.filter(l => l.misura === 'incasso').map(l => l.id));
  const perSerata = {}; for (const r of risR.results) (perSerata[r.serata_id] ||= {})[r.persona_id] = r;
  const val = (s, pid) => { const r = (perSerata[s.id] || {})[pid]; if (!r) return 0; return incasso.has(s.fmt) ? (r.e || 0) : r.b + r.t; };
  const conta = s => s.data >= imp.stagione_inizio && (!filtro || s.loc === filtro || s.fmt === filtro);
  // totali personali della stagione (e del filtro)
  const pers = {}, segni = {};
  for (const s of serR.results) if (conta(s)) for (const r of Object.values(perSerata[s.id] || {})) {
    const o = pers[r.persona_id] ||= { b: 0, t: 0, e: 0 }; o.b += r.b; o.t += r.t; o.e += r.e || 0;
  }
  // "a segno": più del miglior risultato personale nelle 2 serate precedenti dello stesso format
  // (anche fuori stagione, per il confronto); si contano solo le serate della stagione e del filtro
  const gruppi = {}; for (const s of serR.results) (gruppi[s.fmt || ''] ||= []).push(s);
  for (const l of Object.values(gruppi)) l.forEach((s, i) => {
    if (!conta(s)) return;
    const prev = l.slice(Math.max(0, i - 2), i);
    for (const pid of Object.keys(perSerata[s.id] || {})) {
      const v = val(s, pid), best = Math.max(0, ...prev.map(p => val(p, pid)));
      if (v > best) segni[pid] = (segni[pid] || 0) + 1;
    }
  });
  const figli = {}; for (const p of persone) if (p.parent) (figli[p.parent] ||= []).push(p.id);
  const memo = {};
  const team = (id, vis = new Set()) => {
    if (memo[id]) return memo[id]; if (vis.has(id)) return { b: 0, t: 0, e: 0, s: 0 }; vis.add(id);
    const a = { ...(pers[id] || { b: 0, t: 0, e: 0 }), s: segni[id] || 0 };
    for (const c of figli[id] || []) { const v = team(c, vis); a.b += v.b; a.t += v.t; a.e += v.e; a.s += v.s; }
    return memo[id] = a;
  };
  const mio = admin ? null : ramo(persone, me.persona_id);
  const righe = [];
  for (const p of persone) {
    // PR: risultati personali; Capi PR e Capi staff: personali + tutto il gruppo (bonus compresi)
    const v = p.ruolo === 'pr' ? { ...(pers[p.id] || { b: 0, t: 0, e: 0 }), s: segni[p.id] || 0 } : team(p.id);
    const persoTot = v.b + v.t; if (!persoTot && !v.e) continue;
    const punti = Math.floor(persoTot / imp.punti_persone) + Math.floor(v.e / 100 / imp.punti_euro) + v.s * imp.punti_segno;
    const vede = admin || mio.has(p.id);
    const r = { nome: [p.nome, p.cognome].filter(Boolean).join(' ') || 'Senza nome', ruolo: p.ruolo, punti, mio: !admin && vede };
    if (vede) r.id = p.id; // la classifica mostra solo nome e punti
    righe.push(r);
  }
  return { imp, filtro, righe };
}

/* ---------- API ---------- */
async function api(req, env, me, path) {
  const m = req.method, seg = path.split('/').filter(Boolean); // es. ['persone', 'id']
  const admin = me.ruolo === 'admin';
  if (m !== 'GET' && !(req.headers.get('content-type') || '').includes('application/json')) return err('Richiesta non valida', 415);
  if (m !== 'GET' && req.headers.get('x-ver') !== VER) return json({ error: 'Il sito è stato aggiornato: ricarico la pagina, poi riprova.', reload: true }, 409);
  const body = m === 'POST' || m === 'PUT' ? await req.json().catch(() => ({})) : {};

  if (m === 'GET' && seg[0] === 'data') {
    const persone = await tutte(env);
    const [loc, ser, ris] = await Promise.all([
      env.DB.prepare('SELECT * FROM locali').all(), env.DB.prepare('SELECT * FROM serate').all(), env.DB.prepare('SELECT * FROM risultati').all()]);
    const vis = admin ? null : ramo(persone, me.persona_id);
    const mappa = {};
    for (const r of ris.results) if (!vis || vis.has(r.persona_id)) (mappa[r.serata_id] ||= {})[r.persona_id] = { b: r.b, t: r.t, e: r.e || 0 };
    const out = {
      ver: VER, me, persone: vis ? persone.filter(p => vis.has(p.id)) : persone, locali: loc.results,
      serate: ser.results.map(s => ({ ...s, ris: mappa[s.id] || {} })),
    };
    out.imp = await impostazioni(env);
    if (admin) out.utenti = (await env.DB.prepare('SELECT * FROM utenti ORDER BY email').all()).results;
    return json(out);
  }

  if (seg[0] === 'persone') {
    const persone = await tutte(env), id = seg[1] || null;
    const esistente = id ? persone.find(p => p.id === id) : null;
    if (id && !esistente) return err('Persona non trovata', 404);
    const vis = admin ? null : ramo(persone, me.persona_id);
    if (vis && id && !vis.has(id)) return err('Non fa parte del tuo ramo', 403);

    if (m === 'DELETE' && id) {
      if (!admin && id === me.persona_id) return err('Non puoi eliminare te stesso', 403);
      // i collegati passano al superiore della persona eliminata
      await env.DB.batch([
        env.DB.prepare('UPDATE persone SET parent = ? WHERE parent = ?').bind(esistente.parent, id),
        env.DB.prepare('DELETE FROM persone WHERE id = ?').bind(id),
        env.DB.prepare('DELETE FROM utenti WHERE persona_id = ?').bind(id)]);
      return json({ ok: true });
    }
    if (m === 'POST' || m === 'PUT') {
      if (m === 'PUT' && !id) return err('Manca la persona');
      const d = pulisci(body);
      if (!admin) {
        if (id === me.persona_id) { d.ruolo = esistente.ruolo; d.parent = esistente.parent; } // il capo staff può aggiornare solo i propri dati
        else {
          if (!d.parent || !vis.has(d.parent)) return err('Collega la persona a qualcuno del tuo ramo', 403);
        }
      }
      const e = controllaAlbero(d, id, persone); if (e) return err(e);
      const nid = id || uid(), ora = new Date().toISOString();
      if (id) await env.DB.prepare('UPDATE persone SET nome=?,cognome=?,anno=?,scuola=?,zona=?,tel=?,note=?,ruolo=?,parent=?,aggiornato=? WHERE id=?')
        .bind(d.nome, d.cognome, d.anno, d.scuola, d.zona, d.tel, d.note, d.ruolo, d.parent, ora, id).run();
      else await env.DB.prepare('INSERT INTO persone (id,nome,cognome,anno,scuola,zona,tel,note,ruolo,parent,creato_da,aggiornato) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)')
        .bind(nid, d.nome, d.cognome, d.anno, d.scuola, d.zona, d.tel, d.note, d.ruolo, d.parent, me.email, ora).run();
      return json({ ok: true, id: nid });
    }
  }

  if (m === 'GET' && seg[0] === 'punti') return json(await classificaPunti(env, me, admin, new URL(req.url).searchParams.get('f') || ''));

  if (!admin) return err('Solo l\'amministratore può farlo', 403);

  if (seg[0] === 'impostazioni' && m === 'PUT') {
    const ini = txt(body.stagione_inizio, 10), pp = parseInt(body.punti_persone, 10), pe = parseInt(body.punti_euro, 10), ps = parseInt(body.punti_segno, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(ini)) return err('Data di inizio stagione non valida.');
    if (!(pp >= 1 && pp <= 10000) || !(pe >= 1 && pe <= 1000000)) return err('Le soglie dei punti devono essere numeri maggiori di zero.');
    if (!(ps >= 0 && ps <= 1000)) return err('Il bonus per chi va a segno deve essere un numero da 0 in su.');
    const q = 'INSERT INTO impostazioni (chiave,valore) VALUES (?,?) ON CONFLICT(chiave) DO UPDATE SET valore=excluded.valore';
    await env.DB.batch([env.DB.prepare(q).bind('stagione_inizio', ini), env.DB.prepare(q).bind('punti_persone', String(pp)), env.DB.prepare(q).bind('punti_euro', String(pe)), env.DB.prepare(q).bind('punti_segno', String(ps))]);
    return json({ ok: true });
  }

  if (seg[0] === 'locali') {
    if (m === 'POST') {
      const nome = txt(body.nome, 80), tipo = body.tipo === 'format' ? 'format' : 'locale';
      if (!nome) return err('Scrivi il nome.');
      const eta = etaMin(body.eta_min);
      if (tipo === 'format' && eta == null) return err('Indica l\'età minima del format (es. 14).');
      const id = uid();
      await env.DB.prepare('INSERT INTO locali (id,nome,tipo,eta_min,misura) VALUES (?,?,?,?,?)').bind(id, nome, tipo, tipo === 'format' ? eta : null, tipo === 'format' ? misura(body.misura) : null).run();
      return json({ ok: true, id });
    }
    if (m === 'PUT' && seg[1]) {
      const l = await env.DB.prepare('SELECT * FROM locali WHERE id=?').bind(seg[1]).first();
      if (!l) return err('Non trovato', 404);
      const nome = txt(body.nome, 80); if (!nome) return err('Scrivi il nome.');
      const eta = etaMin(body.eta_min);
      if (l.tipo === 'format' && eta == null) return err('Indica l\'età minima del format (es. 14).');
      await env.DB.prepare('UPDATE locali SET nome=?, eta_min=?, misura=? WHERE id=?').bind(nome, l.tipo === 'format' ? eta : null, l.tipo === 'format' ? misura(body.misura) : null, seg[1]).run();
      return json({ ok: true });
    }
    if (m === 'DELETE' && seg[1]) {
      const u = await env.DB.prepare('SELECT COUNT(*) n FROM serate WHERE loc=?1 OR fmt=?1').bind(seg[1]).first();
      if (u.n) return err(`Usato in ${u.n} serate: non si può eliminare.`);
      await env.DB.prepare('DELETE FROM locali WHERE id=?').bind(seg[1]).run(); return json({ ok: true });
    }
  }

  if (seg[0] === 'serate') {
    const id = seg[1] || null;
    if (m === 'DELETE' && id) {
      await env.DB.batch([env.DB.prepare('DELETE FROM risultati WHERE serata_id=?').bind(id), env.DB.prepare('DELETE FROM serate WHERE id=?').bind(id)]);
      return json({ ok: true });
    }
    if (m === 'POST' || m === 'PUT') {
      const data = txt(body.data, 10); if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) return err('Inserisci la data della serata.');
      const sid = id || uid(), st = [];
      st.push(env.DB.prepare('INSERT INTO serate (id,data,nome,loc,fmt) VALUES (?1,?2,?3,?4,?5) ON CONFLICT(id) DO UPDATE SET data=?2,nome=?3,loc=?4,fmt=?5')
        .bind(sid, data, txt(body.nome, 120), body.loc || null, body.fmt || null));
      st.push(env.DB.prepare('DELETE FROM risultati WHERE serata_id=?').bind(sid));
      for (const [pid, r] of Object.entries(body.ris || {})) {
        const b = Math.max(0, parseInt(r && r.b, 10) || 0), t = Math.max(0, parseInt(r && r.t, 10) || 0), e = Math.max(0, parseInt(r && r.e, 10) || 0); // e = incasso tavoli in centesimi
        if (b >= 1 || t >= 1 || e > 0) st.push(env.DB.prepare('INSERT INTO risultati (serata_id,persona_id,b,t,e) VALUES (?,?,?,?,?)').bind(sid, txt(pid, 40), b, t, e));
      }
      await env.DB.batch(st); return json({ ok: true, id: sid });
    }
  }

  if (seg[0] === 'utenti') {
    if (m === 'POST') {
      const email = txt(body.email, 200).toLowerCase();
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return err('Email non valida.');
      const p = await env.DB.prepare('SELECT ruolo FROM persone WHERE id=?').bind(body.persona_id || '').first();
      if (!p || p.ruolo !== 'staff') return err('Scegli un Capo staff.');
      await env.DB.prepare('INSERT INTO utenti (email,ruolo,persona_id) VALUES (?1,\'staff\',?2) ON CONFLICT(email) DO UPDATE SET persona_id=?2').bind(email, body.persona_id).run();
      return json({ ok: true });
    }
    if (m === 'DELETE' && seg[1]) { await env.DB.prepare('DELETE FROM utenti WHERE email=?').bind(decodeURIComponent(seg[1]).toLowerCase()).run(); return json({ ok: true }); }
  }
  return err('Richiesta non riconosciuta', 404);
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const email = await chiSei(req, env);
    if (email && email.config) return msgPage('Configurazione incompleta', 'Mancano TEAM_DOMAIN e POLICY_AUD nelle variabili del Worker.');
    if (!email) return msgPage('Accesso non valido', 'Apri il sito dal link e accedi con la tua email.');
    const admins = (env.ADMIN_EMAILS || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
    let me = null;
    if (admins.includes(email)) me = { email, ruolo: 'admin', persona_id: null };
    else {
      const u = await env.DB.prepare('SELECT * FROM utenti WHERE email=?').bind(email).first();
      if (u && u.persona_id) me = { email, ruolo: 'staff', persona_id: u.persona_id };
    }
    const isApi = url.pathname.startsWith('/api/');
    if (!me) return isApi ? err('Non autorizzato', 403) : msgPage('Non sei abilitato', `L'email <b>${email.replace(/[<>&"]/g, '')}</b> non è tra quelle autorizzate. Chiedi all'amministratore di aggiungerti.`);
    if (isApi) {
      try { return await api(req, env, me, url.pathname.slice(5)); }
      catch (e) { return err('Errore del server: ' + (e && e.message || e), 500); }
    }
    return page(HTML);
  },
};
